-- 203 (14/11, lô 44, chủ dự án): hai đề NHÁP đầu tiên « TCF Canada · Đề 1 » (level TCF) và « TCF Pháp · Đề 1 »
-- (level TCF_TP). Khung theo tài liệu đề TCF chủ dự án gửi, nội dung do FRACILE soạn (không chép đề thật).
-- Nghe: mỗi câu một audio riêng phát một lần (CẦN migration 202 chạy trước). Máy dựng: scripts/nhap/lo44_tcf_de_moi.mjs.
-- Chạy lại an toàn: bài trùng id thì bỏ qua, đề trùng tên thì không tạo thêm.
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44cade1co', 'exam', 'TCF Canada · Đề 1 : Compréhension orale', 'TCF', array['Écoute']::text[], 'practice', null, 35, '<p><strong>Compréhension orale : 39 questions, 35 minutes.</strong> Chaque document est diffusé <strong>une seule fois</strong> : lancez l''écoute de la question, puis choisissez la bonne réponse. Pour certaines questions, les propositions ne sont pas écrites : vous les entendez seulement.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44caco01', 'lo44cade1co', 1, 'qcm', 'Écoutez les quatre propositions. Choisissez celle qui correspond à l''image.', '{"anh":"https://ouch-prod-var-cdn.icons8.com/rh/illustrations/previews/faWP68YLZ2-CC9Ih.webp","options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-01.mp3"}'::jsonb, '{"answer":1,"model":"A. Une femme dort sous un arbre. B. Une jeune femme lit, allongée sur une couverture. C. Une femme court dans un parc. D. Une femme écrit une lettre à une table."}'::jsonb, 'Sur l''image, la jeune femme est allongée sur une couverture et lit un livre.'),
  ('lo44caco02', 'lo44cade1co', 2, 'qcm', 'Écoutez les quatre propositions. Choisissez celle qui correspond à l''image.', '{"anh":"https://ouch-prod-var-cdn.icons8.com/gq/illustrations/previews/NFohn2nBlRfHNVmg.webp","options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-02.mp3"}'::jsonb, '{"answer":2,"model":"A. Le cuisinier coupe des légumes. B. Le cuisinier lave une casserole. C. Le cuisinier présente un poulet rôti. D. Le cuisinier sert une soupe à un client."}'::jsonb, 'Le cuisinier tient une assiette avec un poulet rôti.'),
  ('lo44caco03', 'lo44cade1co', 3, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-03.mp3"}'::jsonb, '{"answer":1,"model":"Excusez-moi, la gare, c''est loin d''ici ?\nA. Il est huit heures. B. Non, c''est à cinq minutes à pied. C. Oui, j''ai un billet. D. Je vais bien, merci."}'::jsonb, 'On demande une distance : la réponse logique indique le temps pour y aller.'),
  ('lo44caco04', 'lo44cade1co', 4, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-04.mp3"}'::jsonb, '{"answer":0,"model":"Tu veux un café ou un thé ?\nA. Un thé, s''il te plaît. B. À la maison. C. Demain matin. D. Il fait froid."}'::jsonb, 'La question propose un choix entre deux boissons.'),
  ('lo44caco05', 'lo44cade1co', 5, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-05.mp3"}'::jsonb, '{"answer":3,"model":"Clinique médicale du Plateau, bonjour.\nBonjour madame, j''aimerais prendre rendez-vous avec un médecin cette semaine, si possible.\nA. Le docteur est très gentil. B. La pharmacie ferme à dix-huit heures. C. Oui, j''ai mal à la tête. D. Jeudi à quinze heures, ça vous convient ?"}'::jsonb, 'La secrétaire répond à une demande de rendez-vous en proposant un jour et une heure.'),
  ('lo44caco06', 'lo44cade1co', 6, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-06.mp3"}'::jsonb, '{"answer":3,"model":"Bonjour, je cherche un appartement de deux chambres, près du métro.\nA. Le métro est en panne aujourd''hui. B. Je préfère habiter à la campagne. C. Mon frère a trois enfants. D. J''en ai un rue Saint-Denis, à deux minutes de la station."}'::jsonb, 'L''agent répond en proposant un logement qui correspond à la demande.'),
  ('lo44caco07', 'lo44cade1co', 7, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-07.mp3"}'::jsonb, '{"answer":0,"model":"Le cours de yoga de mardi est annulé, mais tu peux venir jeudi.\nA. D''accord, je viendrai jeudi alors. B. Le yoga vient de l''Inde. C. Mardi, j''ai acheté un tapis. D. Non, je n''ai pas de voiture."}'::jsonb, 'On propose un autre jour : la réponse accepte ce nouveau jour.'),
  ('lo44caco08', 'lo44cade1co', 8, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-08.mp3"}'::jsonb, '{"answer":2,"model":"Est-ce que je peux payer par carte ?\nA. La carte est sur la table. B. Oui, j''aime beaucoup les cartes postales. C. Désolée, notre terminal ne fonctionne pas aujourd''hui : seulement en argent comptant. D. Le magasin ouvre à neuf heures."}'::jsonb, 'La question porte sur le moyen de paiement ; la vendeuse explique qu''il faut payer en argent comptant.'),
  ('lo44caco09', 'lo44cade1co', 9, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["D''apporter un document.","D''acheter des médicaments.","D''appeler leur mère.","D''aller chez le médecin."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-09.mp3"}'::jsonb, '{"answer":0,"model":"Bonjour Julie, c''est Marc. Je suis à la pharmacie, mais j''ai oublié l''ordonnance de maman à la maison. Est-ce que tu peux me l''apporter avant midi ? Merci !\nQue demande Marc à Julie ?"}'::jsonb, 'Marc a oublié l''ordonnance (un papier) et demande à Julie de l''apporter.'),
  ('lo44caco10', 'lo44cade1co', 10, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Pour compter les marchandises.","Pour une fête du personnel.","À cause d''une panne d''électricité.","À cause de la tempête de neige."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-10.mp3"}'::jsonb, '{"answer":0,"model":"Chers clients, notre magasin fermera exceptionnellement à dix-huit heures ce soir en raison de l''inventaire annuel. Merci de vous diriger dès maintenant vers les caisses.\nPourquoi le magasin ferme-t-il plus tôt ?"}'::jsonb, '« l''inventaire annuel » : on compte tous les produits du magasin.'),
  ('lo44caco11', 'lo44cade1co', 11, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Demander l''accord du directeur.","Changer de service.","S''inscrire avant la fin de la semaine.","Travailler le vendredi."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-11.mp3"}'::jsonb, '{"answer":2,"model":"Tu as vu ? L''entreprise propose maintenant deux jours de télétravail par semaine.\nOui, mais il faut s''inscrire auprès des ressources humaines avant vendredi. Sinon, on doit attendre le mois prochain.\nQue faut-il faire pour obtenir le télétravail ?"}'::jsonb, 'La femme précise qu''il faut s''inscrire auprès des ressources humaines avant vendredi.'),
  ('lo44caco12', 'lo44cade1co', 12, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["La façon d''acheter les billets.","Le prix pour les enfants.","La date du festival.","Le lieu du festival."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-12.mp3"}'::jsonb, '{"answer":0,"model":"Le festival des lanternes du Jardin botanique ouvre ses portes vendredi. Nouveauté cette année : les billets sont vendus uniquement en ligne, et il n''y aura plus de guichet sur place. L''entrée reste gratuite pour les moins de douze ans.\nQu''est-ce qui change cette année ?"}'::jsonb, 'Les billets sont vendus « uniquement en ligne », le guichet disparaît ; l''entrée des enfants ne change pas.'),
  ('lo44caco13', 'lo44cade1co', 13, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Pour payer sa facture.","Pour changer l''heure de l''installation.","Pour annuler son abonnement.","Pour signaler une panne."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-13.mp3"}'::jsonb, '{"answer":1,"model":"Bonjour, ici le service à la clientèle de VitaFibre. Notre technicien passera demain entre huit heures et midi pour installer votre connexion Internet. Si ce créneau ne vous convient pas, merci de nous rappeler au plus tard ce soir.\nPourquoi la cliente devrait-elle rappeler ce soir ?"}'::jsonb, 'On rappelle « Si ce créneau ne vous convient pas », c''est-à-dire pour modifier l''horaire.'),
  ('lo44caco14', 'lo44cade1co', 14, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Un autre horaire ou une autre formule.","Le remboursement de l''inscription.","Un rendez-vous avec le professeur.","Un autre cours de mathématiques."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-14.mp3"}'::jsonb, '{"answer":0,"model":"Je voulais m''inscrire au cours de statistiques, mais il est complet.\nIl reste encore quelques places dans le groupe du soir, le mercredi. Sinon, la version en ligne commence en janvier.\nQue propose le conseiller ?"}'::jsonb, 'Il propose le groupe du mercredi soir ou la version en ligne de janvier.'),
  ('lo44caco15', 'lo44cade1co', 15, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["La taille du métro.","Le prix des transports.","Le climat de la ville.","L''attitude des habitants."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-15.mp3"}'::jsonb, '{"answer":3,"model":"Je suis arrivée à Montréal il y a deux ans. Au début, ce qui m''a le plus surprise, ce n''est pas le froid, je m''y attendais. C''est la gentillesse des gens dans le métro : dès qu''on a l''air un peu perdu, quelqu''un vient vous aider.\nQu''est-ce qui a surpris cette femme ?"}'::jsonb, 'Elle dit que le froid ne l''a pas surprise ; c''est la gentillesse des gens.'),
  ('lo44caco16', 'lo44cade1co', 16, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["À cause d''une règle imposée par le propriétaire.","À cause du mauvais temps.","Parce que le chalet est plus grand.","Parce que l''oncle l''a demandé."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-16.mp3"}'::jsonb, '{"answer":0,"model":"Salut, c''est Karim. Pour la fête de samedi, finalement, on ne la fait pas chez moi : mon propriétaire refuse tout bruit après vingt-deux heures. On se retrouve au chalet de mon oncle, je t''envoie l''adresse.\nPourquoi la fête change-t-elle de lieu ?"}'::jsonb, 'Le propriétaire de Karim interdit le bruit après 22 h.'),
  ('lo44caco17', 'lo44cade1co', 17, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Prendre les transports en commun.","Éviter le centre-ville.","Rouler moins vite sur le pont.","Partir plus tôt le matin."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-17.mp3"}'::jsonb, '{"answer":0,"model":"Information circulation : en raison des travaux sur le pont, une seule voie sera ouverte dans chaque direction jusqu''au quinze novembre. La Ville conseille aux automobilistes d''utiliser le transport en commun pendant cette période.\nQue recommande la Ville ?"}'::jsonb, '« La Ville conseille… d''utiliser le transport en commun ».'),
  ('lo44caco18', 'lo44cade1co', 18, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Un horaire réduit.","Un poste différent.","Des avantages qui viendront plus tard.","Un meilleur salaire dès le début."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-18.mp3"}'::jsonb, '{"answer":2,"model":"Le poste me plaît beaucoup, mais le salaire est un peu bas pour moi.\nJe comprends. Nous ne pouvons pas changer le salaire de départ. En revanche, vous auriez une augmentation après six mois, et une semaine de vacances supplémentaire.\nQu''offre l''entreprise au candidat ?"}'::jsonb, 'Le salaire de départ ne change pas, mais il y aura une augmentation après six mois et plus de vacances.'),
  ('lo44caco19', 'lo44cade1co', 19, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Des jeux vidéo.","Des ordinateurs portables.","Des instruments de musique.","Du matériel de bricolage et de jardinage."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-19.mp3"}'::jsonb, '{"answer":3,"model":"La bibliothèque du quartier lance un nouveau service : le prêt d''outils. Perceuse, échelle, matériel de jardinage : il suffit de présenter votre carte d''abonné. Le prêt dure une semaine et il est gratuit.\nQue peut-on désormais emprunter à la bibliothèque ?"}'::jsonb, 'Perceuse, échelle, matériel de jardinage : ce sont des outils.'),
  ('lo44caco20', 'lo44cade1co', 20, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Attirer une nouvelle clientèle.","Soutenir les agriculteurs de la région.","Limiter le gaspillage alimentaire.","Augmenter leurs profits."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-20.mp3"}'::jsonb, '{"answer":2,"model":"Depuis l''an dernier, plusieurs épiceries de Québec vendent à prix réduit des fruits et légumes dits « moches », abîmés ou mal formés. Pour ces commerçants, l''objectif n''est pas tant de faire des bénéfices que de réduire le gaspillage, qui concerne encore près d''un tiers de la production.\nQuel est l''objectif principal de ces épiceries ?"}'::jsonb, '« l''objectif n''est pas tant de faire des bénéfices que de réduire le gaspillage ».'),
  ('lo44caco21', 'lo44cade1co', 21, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Prendre du poids.","Perdre la mémoire.","Mal dormir la nuit suivante.","Se sentir encore plus fatigué."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-21.mp3"}'::jsonb, '{"answer":3,"model":"On associe souvent la sieste à la paresse. Pourtant, une courte pause d''une vingtaine de minutes en début d''après-midi améliore la vigilance et la mémoire. Au-delà d''une demi-heure, en revanche, on entre dans un sommeil profond, et l''on risque de se réveiller encore plus fatigué qu''avant.\nSelon la chronique, quel est le risque d''une sieste trop longue ?"}'::jsonb, 'Une sieste de plus d''une demi-heure fait risquer de « se réveiller encore plus fatigué ».'),
  ('lo44caco22', 'lo44cade1co', 22, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Ses clients utilisent le vélo au quotidien.","Son atelier ferme pendant l''hiver.","Le vélo est un loisir coûteux.","Les sportifs réparent eux-mêmes leur vélo."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-22.mp3"}'::jsonb, '{"answer":0,"model":"Quand j''ai ouvert mon atelier de réparation de vélos, je pensais que mes clients seraient surtout des sportifs. En fait, ce sont des gens qui vont travailler à vélo toute l''année, même en plein hiver, et qui ont besoin d''une réparation rapide pour ne pas perdre une journée.\nQu''a découvert cet entrepreneur ?"}'::jsonb, 'Ses clients sont des personnes qui vont travailler à vélo toute l''année.'),
  ('lo44caco23', 'lo44cade1co', 23, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les aliments coûtent trop cher.","Les élèves ne seront pas intéressés.","Les écoles risquent de manquer de moyens.","Les enseignants ne sont pas assez formés."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-23.mp3"}'::jsonb, '{"answer":2,"model":"Des cours de cuisine obligatoires au secondaire : bonne idée, selon vous ?\nSur le principe, oui. Mais je crains qu''on ajoute encore une matière au programme sans donner aux écoles les cuisines équipées ni le personnel nécessaires.\nQuelle réserve l''homme exprime-t-il ?"}'::jsonb, 'Il craint qu''on ne donne pas aux écoles « les cuisines équipées ni le personnel nécessaires ».'),
  ('lo44caco24', 'lo44cade1co', 24, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Une partie du loyer.","Des soins médicaux.","Des cours particuliers.","Du temps passé avec les résidents."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-24.mp3"}'::jsonb, '{"answer":3,"model":"Dans cette résidence pour aînés de Sherbrooke, des étudiants sont logés gratuitement. En échange, ils consacrent quelques heures par semaine à partager un repas, une partie de cartes ou une promenade avec les résidents. Pour la direction, le but est de rompre l''isolement, certainement pas de remplacer le personnel soignant.\nQue donnent les étudiants en échange du logement ?"}'::jsonb, 'Ils partagent repas, cartes ou promenades avec les résidents : c''est de la compagnie, pas des soins.'),
  ('lo44caco25', 'lo44cade1co', 25, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Le mazout reste moins cher.","L''aide arrive trop tard.","La thermopompe pollue davantage.","L''aide reste insuffisante pour les ménages modestes."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-25.mp3"}'::jsonb, '{"answer":3,"model":"Le gouvernement a annoncé une aide financière pour les ménages qui remplacent leur chauffage au mazout par une thermopompe. Mais les associations de consommateurs rappellent que l''installation coûte souvent le double du montant de l''aide, ce qui exclut de fait les ménages les plus modestes.\nQue reprochent les associations de consommateurs ?"}'::jsonb, 'L''installation coûte le double de l''aide : les ménages modestes ne peuvent pas en profiter.'),
  ('lo44caco26', 'lo44cade1co', 26, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["C''est un signe de retard.","Il faut le corriger très tôt.","C''est une façon efficace de communiquer.","Il disparaît à l''adolescence."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-26.mp3"}'::jsonb, '{"answer":2,"model":"Contrairement à une idée reçue, les enfants bilingues ne prennent pas de retard dans l''apprentissage du langage. Il leur arrive de mélanger les deux langues dans une même phrase, mais il s''agit d''une stratégie de communication : ils empruntent le mot qui leur vient le plus vite. Ce n''est pas une confusion.\nQue dit la spécialiste du mélange des langues ?"}'::jsonb, '« il s''agit d''une stratégie de communication… Ce n''est pas une confusion ».'),
  ('lo44caco27', 'lo44cade1co', 27, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Pour voir le résultat concret de son travail.","Pour travailler en équipe.","Pour gagner davantage.","Pour avoir plus de temps libre."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-27.mp3"}'::jsonb, '{"answer":0,"model":"J''ai quitté mon emploi dans la finance pour devenir ébéniste. Je gagne moins, c''est vrai. Mais je n''ai plus l''impression de passer mes journées à produire des tableaux que personne ne lit. Le soir, je peux toucher ce que j''ai fabriqué.\nPourquoi cet homme a-t-il changé de métier ?"}'::jsonb, 'Le soir, il peut « toucher ce que j''ai fabriqué » : il voit le résultat concret de son travail.'),
  ('lo44caco28', 'lo44cade1co', 28, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Recycler davantage de déchets.","Adapter la collecte aux besoins réels.","Réduire le nombre de poubelles.","Faire payer les habitants qui jettent trop."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-28.mp3"}'::jsonb, '{"answer":1,"model":"La Ville a installé des capteurs dans les poubelles publiques. Ils signalent automatiquement lorsqu''elles sont pleines, ce qui permet d''organiser les tournées de ramassage selon les besoins réels plutôt que selon un calendrier fixe. Résultat : moins de camions sur les routes et des rues plus propres.\nQuel est l''avantage de ce système ?"}'::jsonb, 'Les tournées se font « selon les besoins réels plutôt que selon un calendrier fixe ».'),
  ('lo44caco29', 'lo44cade1co', 29, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["La langue du pays d''accueil.","Un problème d''argent lié à son logement.","La peur de partir seul.","Le peu d''intérêt du stage."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-29.mp3"}'::jsonb, '{"answer":1,"model":"Alors, ce stage à l''étranger, tu le prends ?\nJ''hésite. C''est une chance énorme. Mais ma propriétaire refuse que je sous-loue l''appartement, et je ne peux pas payer deux loyers pendant six mois.\nQu''est-ce qui fait hésiter le jeune homme ?"}'::jsonb, 'Il ne peut pas sous-louer et ne peut pas payer deux loyers.'),
  ('lo44caco30', 'lo44cade1co', 30, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Il défend les travailleurs qui les choisissent.","Il salue leur dimension solidaire.","Il juge leur discours trompeur.","Il souhaite leur interdiction."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-30.mp3"}'::jsonb, '{"answer":2,"model":"On célèbre volontiers l''économie du partage comme une révolution solidaire. Mais une bonne partie des plateformes qui s''en réclament se contentent de mettre en relation des clients et des travailleurs précaires, en prélevant une commission au passage. Le partage, ici, relève davantage de l''argument publicitaire que du projet de société.\nQuel regard le chroniqueur porte-t-il sur ces plateformes ?"}'::jsonb, 'Pour lui, le « partage » est surtout un « argument publicitaire ».'),
  ('lo44caco31', 'lo44cade1co', 31, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les insectes disparaissent pendant les sécheresses.","Le climat fragilise les arbres face à d''autres menaces.","Les arbres meurent surtout de soif.","Les forêts boréales s''étendent vers le nord."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-31.mp3"}'::jsonb, '{"answer":1,"model":"Ce qui nous a frappés, en étudiant les forêts boréales, c''est que les arbres affaiblis par la sécheresse ne meurent pas forcément de soif. Ils deviennent surtout vulnérables aux insectes, qui profitent de leurs défenses amoindries. Autrement dit, le climat agit souvent de manière indirecte.\nQu''ont constaté les chercheurs ?"}'::jsonb, 'Les arbres affaiblis deviennent « vulnérables aux insectes » : le climat agit « de manière indirecte ».'),
  ('lo44caco32', 'lo44cade1co', 32, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les médias ignorent les mouvements citoyens.","Les mots-clics n''ont jamais aucun effet.","Les réseaux ne suffisent pas à faire durer une mobilisation.","Les réseaux nuisent aux mouvements citoyens."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-32.mp3"}'::jsonb, '{"answer":2,"model":"Je ne conteste pas que les réseaux sociaux aient permis à des mouvements citoyens d''émerger. Ce que je conteste, c''est l''idée qu''ils suffiraient. Une mobilisation qui se limite à des partages et à des mots-clics s''essouffle dès que l''actualité passe à autre chose.\nQuelle est la position de l''intervenante ?"}'::jsonb, 'Elle reconnaît leur rôle, mais une mobilisation limitée aux réseaux « s''essouffle ».'),
  ('lo44caco33', 'lo44cade1co', 33, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["C''est un compromis qui a sauvé le bâtiment.","Elle a fait l''unanimité.","Elle remplace l''église par une bibliothèque.","Elle rend l''église à son usage d''origine."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-33.mp3"}'::jsonb, '{"answer":0,"model":"La restauration de cette église du dix-neuvième siècle a divisé le quartier. Certains voulaient lui rendre sa fonction religieuse ; d''autres y voyaient l''occasion de créer une bibliothèque. La solution retenue, un espace culturel qui accueille aussi des célébrations ponctuelles, n''a pleinement satisfait personne. Mais elle a évité la démolition.\nQue dit-on de la solution adoptée ?"}'::jsonb, 'Elle « n''a pleinement satisfait personne », mais « a évité la démolition ».'),
  ('lo44caco34', 'lo44cade1co', 34, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Elles renforcent les relations entre voisins.","Elles remplacent les grands parcs.","Elles rafraîchissent la ville en été.","Elles embellissent les façades."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-34.mp3"}'::jsonb, '{"answer":0,"model":"Les ruelles vertes ne se résument pas à quelques bacs à fleurs. Parce qu''elles sont aménagées par les riverains eux-mêmes, elles créent des liens de voisinage que les grands parcs, plus anonymes, favorisent rarement. C''est peut-être là leur véritable réussite, plus encore que leur effet sur la chaleur en été.\nSelon l''urbaniste, quel est le principal intérêt des ruelles vertes ?"}'::jsonb, 'Leur « véritable réussite » : les liens de voisinage, « plus encore » que l''effet sur la chaleur.'),
  ('lo44caco35', 'lo44cade1co', 35, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Son humeur du moment.","Le public qu''elle vise.","Les exigences de son éditeur.","Le thème qu''elle aborde."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-35.mp3"}'::jsonb, '{"answer":3,"model":"On me demande souvent si je choisis d''écrire en français ou en anglais selon mon humeur. En réalité, c''est le sujet qui décide. Mes souvenirs d''enfance ne me viennent qu''en français ; dès que j''aborde le monde du travail, l''anglais s''impose, comme si chaque langue gardait la mémoire d''une partie de ma vie.\nQu''est-ce qui détermine la langue d''écriture de cette autrice ?"}'::jsonb, '« c''est le sujet qui décide ».'),
  ('lo44caco36', 'lo44cade1co', 36, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Il faut tout conserver en mémoire.","L''oubli peut avoir une fonction positive.","La réconciliation exige une mémoire totale.","L''oubli relève toujours du déni."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-36.mp3"}'::jsonb, '{"answer":1,"model":"On oppose trop vite la mémoire et l''oubli, comme si l''une était une vertu et l''autre une faiblesse. Une société qui n''oublierait rien serait condamnée à ressasser ses blessures. L''oubli, lorsqu''il ne relève pas du déni, est aussi ce qui rend possible la réconciliation.\nQuelle thèse défend le philosophe ?"}'::jsonb, 'L''oubli, s''il n''est pas un déni, « rend possible la réconciliation ».'),
  ('lo44caco37', 'lo44cade1co', 37, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Un style trop chargé.","Une intrigue invraisemblable.","Une construction trop classique.","Des personnages qui manquent de consistance."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-37.mp3"}'::jsonb, '{"answer":3,"model":"Ce roman, salué pour l''audace de sa construction, souffre pourtant d''un défaut qui n''est pas mince : à force de multiplier les points de vue, l''auteur finit par dissoudre ses personnages, dont aucun n''acquiert l''épaisseur qui nous attacherait à son sort.\nQue reproche la critique à ce roman ?"}'::jsonb, 'Aucun personnage « n''acquiert l''épaisseur » nécessaire.'),
  ('lo44caco38', 'lo44cade1co', 38, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les familles refusent le télétravail.","Le télétravail accentue des inégalités liées au logement.","Le télétravail améliore la vie familiale.","Le télétravail supprime toute vie privée."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-38.mp3"}'::jsonb, '{"answer":1,"model":"Le télétravail n''a pas aboli la frontière entre vie professionnelle et vie privée ; il l''a déplacée à l''intérieur même du domicile. Ceux qui disposent d''une pièce dédiée parviennent à la maintenir. Pour les autres, la table de la cuisine devient le lieu d''une négociation permanente avec le reste de la famille.\nQue montre la sociologue ?"}'::jsonb, 'La situation dépend de la possibilité d''avoir une pièce dédiée : tout le monde n''est pas logé de la même façon.'),
  ('lo44caco39', 'lo44cade1co', 39, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les toiles décrivent fidèlement la campagne.","Le blanc symbolise la pureté.","Ces paysages expriment une réflexion sur l''effacement.","Le peintre célèbre la beauté de l''hiver."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-ca-de1-co-39.mp3"}'::jsonb, '{"answer":2,"model":"On a longtemps lu les toiles de ce peintre comme de simples paysages enneigés. Une lecture attentive révèle pourtant, sous l''apparente sérénité, une méditation sur la disparition : les silhouettes s''effacent, les chemins ne mènent nulle part, et le blanc, loin d''être neutre, finit par tout recouvrir.\nQuelle interprétation propose l''historien de l''art ?"}'::jsonb, 'Sous la sérénité, une « méditation sur la disparition ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44cade1ce', 'exam', 'TCF Canada · Đề 1 : Compréhension écrite', 'TCF', array['Lecture']::text[], 'practice', null, 60, '<p><strong>Compréhension écrite : 39 questions, 60 minutes.</strong> Lisez chaque document, puis choisissez la bonne réponse.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44cace01', 'lo44cade1ce', 1, 'qcm', 'Où est le père de Léa ?', '{"doc":"<p>Léa,</p><p>Je suis au supermarché. Il n''y a plus de lait à la maison.</p><p>Je rentre à 18 h.</p><p>Papa</p>","options":["Au travail.","Au magasin.","À l''école.","À la maison."]}'::jsonb, '{"answer":1}'::jsonb, '« Je suis au supermarché ».'),
  ('lo44cace02', 'lo44cade1ce', 2, 'qcm', 'Quand la piscine est-elle fermée ?', '{"doc":"<p><strong>PISCINE MUNICIPALE</strong></p><p>Fermée le lundi.</p><p>Du mardi au dimanche : de 7 h à 20 h.</p>","options":["Le soir.","Le matin.","Le dimanche.","Le lundi."]}'::jsonb, '{"answer":3}'::jsonb, '« Fermée le lundi ».'),
  ('lo44cace03', 'lo44cade1ce', 3, 'qcm', 'Que propose Sarah ?', '{"doc":"<p>Salut Tom !</p><p>On va au cinéma samedi soir avec Inès et Hugo. Tu viens ? Réponds vite !</p><p>Sarah</p>","options":["Un cours.","Une sortie.","Un repas.","Un voyage."]}'::jsonb, '{"answer":1}'::jsonb, 'Sarah propose d''aller au cinéma.'),
  ('lo44cace04', 'lo44cade1ce', 4, 'qcm', 'Qu''est-ce qui est à vendre ?', '{"doc":"<p><strong>À VENDRE</strong></p><p>Vélo pour enfant, bleu, très bon état. 40 $.</p><p>Tél. : 514 555 0123</p>","options":["Un vêtement.","Un téléphone.","Un vélo.","Un jouet."]}'::jsonb, '{"answer":2}'::jsonb, '« Vélo pour enfant ».'),
  ('lo44cace05', 'lo44cade1ce', 5, 'qcm', 'Pourquoi Nadia écrit-elle ?', '{"doc":"<p>Bonjour Madame Roy,</p><p>Je suis malade et je ne peux pas venir au cours d''anglais demain. Pouvez-vous m''envoyer les devoirs par courriel ?</p><p>Merci, Nadia</p>","options":["Pour envoyer ses devoirs.","Pour prendre rendez-vous chez le médecin.","Pour s''inscrire à un cours.","Pour prévenir de son absence."]}'::jsonb, '{"answer":3}'::jsonb, 'Nadia est malade et ne viendra pas au cours.'),
  ('lo44cace06', 'lo44cade1ce', 6, 'qcm', 'À quoi servira l''argent de la vente ?', '{"doc":"<p><strong>GRANDE VENTE DE LIVRES USAGÉS</strong></p><p>Samedi 12 octobre, de 10 h à 16 h, à la bibliothèque. Livres à 1 $.</p><p>L''argent servira à acheter de nouveaux livres pour les enfants.</p>","options":["À payer les employés.","À réparer la bibliothèque.","À organiser une fête.","À acheter des livres pour les jeunes."]}'::jsonb, '{"answer":3}'::jsonb, '« L''argent servira à acheter de nouveaux livres pour les enfants ».'),
  ('lo44cace07', 'lo44cade1ce', 7, 'qcm', 'Que demande Paul à son voisin ?', '{"doc":"<p>Bonjour,</p><p>Je pars en vacances du 3 au 10 juillet. Pourriez-vous arroser mes plantes ? Je laisse la clé chez le concierge.</p><p>Merci beaucoup !</p><p>Paul (app. 4)</p>","options":["De s''occuper de ses plantes.","D''appeler le concierge.","De nourrir son chat.","De garder sa clé pendant un an."]}'::jsonb, '{"answer":0}'::jsonb, '« Pourriez-vous arroser mes plantes ? »'),
  ('lo44cace08', 'lo44cade1ce', 8, 'qcm', 'Que doit faire une personne intéressée par le poste ?', '{"doc":"<p><strong>Restaurant Le Petit Érable</strong></p><p>Nous cherchons un serveur ou une serveuse pour les fins de semaine. Expérience non nécessaire.</p><p>Présentez-vous avec votre CV du lundi au jeudi, après 14 h.</p>","options":["Avoir de l''expérience.","Envoyer un courriel.","Téléphoner le samedi.","Venir au restaurant avec son CV."]}'::jsonb, '{"answer":3}'::jsonb, '« Présentez-vous avec votre CV ».'),
  ('lo44cace09', 'lo44cade1ce', 9, 'qcm', 'Pourquoi la sortie change-t-elle de date ?', '{"doc":"<p>Chers parents,</p><p>La sortie au musée prévue le 15 mai est reportée au 22 mai à cause de la grève des autobus scolaires.</p><p>Merci de rendre l''autorisation signée avant le 20 mai.</p><p>La direction</p>","options":["Parce que les parents n''ont pas signé.","À cause de la météo.","À cause d''un problème de transport.","Parce que le musée est fermé."]}'::jsonb, '{"answer":2}'::jsonb, '« à cause de la grève des autobus scolaires ».'),
  ('lo44cace10', 'lo44cade1ce', 10, 'qcm', 'Que faut-il apporter pour récupérer le colis ?', '{"doc":"<p>Bonjour,</p><p>Votre colis n''a pas pu être livré : personne n''était présent à votre adresse.</p><p>Vous pouvez le récupérer au comptoir postal de la rue Laval jusqu''au 30 avril, sur présentation d''une pièce d''identité.</p>","options":["Une lettre de l''expéditeur.","Le numéro de commande.","De l''argent comptant.","Une pièce d''identité."]}'::jsonb, '{"answer":3}'::jsonb, '« sur présentation d''une pièce d''identité ».'),
  ('lo44cace11', 'lo44cade1ce', 11, 'qcm', 'Qu''est-ce qui facilite la participation des parents ?', '{"doc":"<p><strong>Centre communautaire Saint-Michel</strong></p><p>Cours de français gratuits pour les nouveaux arrivants. Groupes du soir et de fin de semaine.</p><p>Halte-garderie offerte pendant les cours. Inscription sur place avec une preuve de résidence.</p>","options":["Les repas offerts.","La garde des enfants pendant les cours.","Le transport gratuit.","Les cours en ligne."]}'::jsonb, '{"answer":1}'::jsonb, '« Halte-garderie offerte pendant les cours ».'),
  ('lo44cace12', 'lo44cade1ce', 12, 'qcm', 'Quel effet les enseignants observent-ils ?', '{"doc":"<p>Depuis septembre, l''école primaire des Érables a supprimé les devoirs écrits à la maison. À la place, les élèves doivent lire vingt minutes chaque soir. Les enseignants constatent déjà que les conflits entre parents et enfants autour des devoirs ont beaucoup diminué.</p>","options":["De meilleures notes en lecture.","Plus de temps libre pour les enfants.","Des élèves plus fatigués.","Moins de tensions dans les familles."]}'::jsonb, '{"answer":3}'::jsonb, 'Les « conflits entre parents et enfants » ont diminué.'),
  ('lo44cace13', 'lo44cade1ce', 13, 'qcm', 'Que propose l''entreprise pour compenser le retard ?', '{"doc":"<p>Madame Tremblay,</p><p>Suite à notre réunion, je vous confirme que la livraison des ordinateurs est repoussée d''une semaine en raison d''une rupture de stock chez notre fournisseur. Pour compenser ce retard, nous vous offrons l''installation gratuite du matériel.</p><p>Cordialement, Luc Martin, service des ventes</p>","options":["Des ordinateurs plus puissants.","Un service gratuit.","Une réduction de prix.","Un remboursement."]}'::jsonb, '{"answer":1}'::jsonb, '« nous vous offrons l''installation gratuite ».'),
  ('lo44cace14', 'lo44cade1ce', 14, 'qcm', 'Où se trouve Claire quand elle écrit cette lettre ?', '{"doc":"<p>Chère Amina,</p><p>Je voulais t''écrire de Vancouver, mais finalement nous avons dû rester à Calgary : la route des Rocheuses était fermée à cause de la neige. Nous avons donc visité les musées de la ville. Nous prendrons l''avion pour Vancouver jeudi.</p><p>Bises, Claire</p>","options":["À Calgary.","Dans l''avion.","Dans les Rocheuses.","À Vancouver."]}'::jsonb, '{"answer":0}'::jsonb, 'Elles ont « dû rester à Calgary » et partiront jeudi.'),
  ('lo44cace15', 'lo44cade1ce', 15, 'qcm', 'Selon ses utilisateurs, quel est le principal avantage du covoiturage ?', '{"doc":"<p>Le covoiturage entre domicile et travail progresse dans la région. Une application met en relation les salariés d''une même zone industrielle. Ses utilisateurs apprécient avant tout les économies réalisées, mais aussi les conversations, qui rendent le trajet moins long.</p>","options":["Rencontrer leur patron.","Arriver plus tôt au travail.","Économiser de l''argent.","Protéger l''environnement."]}'::jsonb, '{"answer":2}'::jsonb, 'Ils apprécient « avant tout les économies ».'),
  ('lo44cace16', 'lo44cade1ce', 16, 'qcm', 'Qu''est-ce qui est demandé aux utilisateurs ?', '{"doc":"<p><strong>Règlement de la salle d''entraînement</strong></p><p>Les résidents peuvent utiliser la salle de 6 h à 22 h. Les enfants de moins de 14 ans doivent être accompagnés d''un adulte.</p><p>Merci de nettoyer les appareils après utilisation.</p>","options":["De payer une cotisation.","De nettoyer le matériel.","De venir avec un enfant.","De réserver à l''avance."]}'::jsonb, '{"answer":1}'::jsonb, '« Merci de nettoyer les appareils après utilisation ».'),
  ('lo44cace17', 'lo44cade1ce', 17, 'qcm', 'Comment fonctionne le nouveau système ?', '{"doc":"<p>Cette année, le festival de musique remplace les gobelets en plastique jetables par des verres réutilisables, consignés à 2 $. Les festivaliers récupèrent leur argent en rapportant le verre à l''un des comptoirs du site.</p>","options":["On paie le verre et on est remboursé en le rapportant.","Les boissons coûtent plus cher.","Les verres sont distribués gratuitement.","Chacun doit apporter son propre verre."]}'::jsonb, '{"answer":0}'::jsonb, 'Verres « consignés à 2 $ », argent récupéré au retour du verre.'),
  ('lo44cace18', 'lo44cade1ce', 18, 'qcm', 'Que faut-il pour participer aux sorties ?', '{"doc":"<p><strong>Club de randonnée Les Sentiers</strong></p><p>Vous aimez marcher et rencontrer des gens ? Chaque dimanche, nous organisons une sortie de niveau facile.</p><p>Pas besoin d''équipement spécial : de bonnes chaussures suffisent. Covoiturage possible depuis la gare.</p>","options":["Un équipement de montagne.","Une excellente condition physique.","Une voiture.","Seulement de bonnes chaussures."]}'::jsonb, '{"answer":3}'::jsonb, '« de bonnes chaussures suffisent ».'),
  ('lo44cace19', 'lo44cade1ce', 19, 'qcm', 'Pourquoi ces personnes lisent-elles moins ?', '{"doc":"<p>Selon une enquête récente, un Canadien sur trois dit lire moins qu''il y a cinq ans. La principale raison avancée n''est pas le manque d''intérêt, mais le manque de temps, en particulier chez les parents de jeunes enfants.</p>","options":["Elles préfèrent les écrans.","Elles manquent de temps.","Les livres sont trop chers.","Elles n''aiment plus lire."]}'::jsonb, '{"answer":1}'::jsonb, 'La principale raison est « le manque de temps ».'),
  ('lo44cace20', 'lo44cade1ce', 20, 'qcm', 'Que reconnaissent les promoteurs de ces serres ?', '{"doc":"<p>Sur les toits de plusieurs supermarchés montréalais poussent désormais des tomates et des laitues. Ces serres urbaines permettent de vendre des légumes cueillis le matin même, sans aucun transport. Leurs promoteurs reconnaissent toutefois que la production reste modeste : elle couvre à peine une petite partie des besoins du magasin et ne remplacera pas l''agriculture traditionnelle.</p>","options":["Le transport reste nécessaire.","Les clients sont méfiants.","Leur production reste limitée.","Leurs légumes sont plus chers."]}'::jsonb, '{"answer":2}'::jsonb, '« la production reste modeste ».'),
  ('lo44cace21', 'lo44cade1ce', 21, 'qcm', 'Quel est le rôle de la ligne téléphonique ?', '{"doc":"<p>Les urgences des hôpitaux sont souvent engorgées par des patients dont l''état ne nécessite pas une prise en charge immédiate. Pour désengorger ces services, la province a mis en place une ligne téléphonique où des infirmières orientent les appelants vers une clinique, une pharmacie ou les urgences, selon la gravité de leurs symptômes.</p>","options":["Diriger chaque patient vers le service adapté.","Donner des conseils de prévention.","Prendre des rendez-vous chez un spécialiste.","Remplacer les médecins de famille."]}'::jsonb, '{"answer":0}'::jsonb, 'Les infirmières « orientent les appelants… selon la gravité ».'),
  ('lo44cace22', 'lo44cade1ce', 22, 'qcm', 'Comment ce livre est-il présenté ?', '{"doc":"<p>Dans cet essai, l''autrice raconte son année sans acheter un seul vêtement neuf. Loin du ton moralisateur qu''on pouvait craindre, elle décrit avec humour ses tentations, ses échecs et les découvertes inattendues qu''a provoquées cette contrainte : la réparation, les échanges entre amies, le plaisir de porter longtemps le même manteau.</p>","options":["Comme une enquête économique.","Comme un récit personnel plein d''humour.","Comme un guide pratique de couture.","Comme une critique sévère de la mode."]}'::jsonb, '{"answer":1}'::jsonb, '« Loin du ton moralisateur… avec humour ».'),
  ('lo44cace23', 'lo44cade1ce', 23, 'qcm', 'Qu''est-ce qui inquiète les commerçants ?', '{"doc":"<p>Le conseil municipal a adopté un règlement qui interdit les nouvelles terrasses chauffées au gaz dans le centre-ville. Les restaurateurs disposent de deux ans pour adapter leurs installations existantes. La mesure vise à réduire les émissions, mais plusieurs commerçants craignent de perdre une clientèle qui fréquente leurs terrasses jusqu''en novembre.</p>","options":["La fermeture du centre-ville.","Un délai trop court.","Le coût des nouvelles terrasses.","Une baisse de la fréquentation."]}'::jsonb, '{"answer":3}'::jsonb, 'Ils craignent « de perdre une clientèle ».'),
  ('lo44cace24', 'lo44cade1ce', 24, 'qcm', 'Qu''apprend-on sur les jeunes adultes ?', '{"doc":"<p>Contrairement à une idée répandue, les jeux de société ne séduisent pas que les nostalgiques. Les ventes progressent fortement chez les 18-35 ans, qui y voient un moyen de passer une soirée entre amis sans écran. Les cafés-jeux, où l''on paie un droit d''entrée pour accéder à des centaines de boîtes, se multiplient dans les grandes villes.</p>","options":["Ils jouent seuls à la maison.","Ils achètent surtout des jeux anciens.","Ils préfèrent les jeux vidéo.","Ils aiment ces jeux pour se déconnecter."]}'::jsonb, '{"answer":3}'::jsonb, 'Ils y voient « un moyen de passer une soirée… sans écran ».'),
  ('lo44cace25', 'lo44cade1ce', 25, 'qcm', 'Que regrettent les réalisateurs ?', '{"doc":"<p>Le cinéma documentaire connaît un regain d''intérêt inattendu. Longtemps cantonné aux festivals et aux chaînes publiques, il trouve aujourd''hui un large public grâce aux plateformes de diffusion en ligne. Les réalisateurs s''en félicitent, tout en regrettant que ces plateformes privilégient les sujets spectaculaires au détriment d''œuvres plus exigeantes.</p>","options":["La baisse du nombre de spectateurs.","Le prix des abonnements.","La disparition des festivals.","La préférence pour les sujets spectaculaires."]}'::jsonb, '{"answer":3}'::jsonb, 'Les plateformes « privilégient les sujets spectaculaires ».'),
  ('lo44cace26', 'lo44cade1ce', 26, 'qcm', 'Pourquoi certains employeurs sont-ils réticents ?', '{"doc":"<p>Le droit à la déconnexion est entré en vigueur dans plusieurs pays. Il oblige les grandes entreprises à définir des plages horaires pendant lesquelles les salariés ne sont pas tenus de répondre aux courriels. Pour les syndicats, c''est une avancée ; pour certains employeurs, une contrainte difficile à concilier avec des équipes réparties sur plusieurs fuseaux horaires.</p>","options":["Leurs équipes travaillent à des heures différentes selon les pays.","Ils veulent lire les courriels de leurs salariés.","La loi ne concerne que les petites entreprises.","Les syndicats s''opposent à la loi."]}'::jsonb, '{"answer":0}'::jsonb, 'Équipes « réparties sur plusieurs fuseaux horaires ».'),
  ('lo44cace27', 'lo44cade1ce', 27, 'qcm', 'Que craignent les chercheurs ?', '{"doc":"<p>Des microplastiques ont été retrouvés jusque dans les lacs les plus isolés du Grand Nord. Transportés par le vent et les courants, ils s''accumulent dans les sédiments et sont ingérés par les poissons. Les chercheurs ignorent encore l''ampleur des effets sur la santé humaine, mais ils redoutent une contamination de toute la chaîne alimentaire.</p>","options":["Que toute la chaîne alimentaire soit touchée.","Que les poissons disparaissent du Nord.","Que les lacs s''assèchent.","Que le vent pollue les villes."]}'::jsonb, '{"answer":0}'::jsonb, 'Ils « redoutent une contamination de toute la chaîne alimentaire ».'),
  ('lo44cace28', 'lo44cade1ce', 28, 'qcm', 'Quel est l''objectif principal du programme ?', '{"doc":"<p>Au cégep, un nouveau programme permet aux étudiants d''obtenir des crédits en participant à des projets communautaires : aide aux devoirs, banque alimentaire, accueil des réfugiés. L''objectif affiché n''est pas seulement de rendre service, mais de développer des compétences de terrain, comme la gestion des conflits ou le travail en équipe.</p>","options":["Réduire le coût des études.","Recruter des bénévoles.","Développer des compétences pratiques.","Supprimer certains cours obligatoires."]}'::jsonb, '{"answer":2}'::jsonb, '« développer des compétences de terrain ».'),
  ('lo44cace29', 'lo44cade1ce', 29, 'qcm', 'Qu''est-ce qui freine surtout les acheteurs ?', '{"doc":"<p>Une étude menée auprès de personnes qui envisagent d''acheter une voiture électrique montre que le prix n''est plus le premier frein. Ce qui retient la majorité des hésitants, c''est la crainte de ne pas trouver de borne de recharge pendant les longs trajets, surtout en hiver, quand l''autonomie des batteries diminue.</p>","options":["Le coût de l''entretien.","La petite taille des voitures.","Le prix des véhicules.","L''inquiétude liée à la recharge."]}'::jsonb, '{"answer":3}'::jsonb, '« la crainte de ne pas trouver de borne de recharge ».'),
  ('lo44cace30', 'lo44cade1ce', 30, 'qcm', 'Qu''est-ce que cette étude met en évidence ?', '{"doc":"<p>Des chercheurs ont observé que les corneilles sont capables de reconnaître des visages humains et de transmettre cette information à leurs congénères. Des oiseaux qui n''avaient jamais été confrontés à une personne jugée menaçante l''évitaient pourtant, plusieurs années plus tard, après avoir vu d''autres corneilles donner l''alerte. Pour les auteurs de l''étude, ce comportement témoigne d''une forme d''apprentissage social longtemps considérée comme propre aux primates.</p>","options":["Une capacité de transmission entre oiseaux.","La peur naturelle des oiseaux face aux humains.","La supériorité des primates.","La mémoire très courte des corneilles."]}'::jsonb, '{"answer":0}'::jsonb, 'Des oiseaux évitent une personne « après avoir vu d''autres corneilles donner l''alerte ».'),
  ('lo44cace31', 'lo44cade1ce', 31, 'qcm', 'À quel paradoxe les spécialistes sont-ils confrontés ?', '{"doc":"<p>Les spécialistes de la petite enfance se heurtent à un paradoxe. Jamais les parents n''ont eu accès à autant d''informations sur le développement de leur enfant ; jamais pourtant ils ne se sont déclarés aussi inquiets. La profusion de conseils, souvent contradictoires, nourrit moins la confiance que le sentiment de ne jamais en faire assez.</p>","options":["Les parents manquent d''informations fiables.","Les conseils sont devenus trop rares.","L''abondance d''informations rend les parents plus anxieux.","Les enfants se développent moins bien qu''avant."]}'::jsonb, '{"answer":2}'::jsonb, 'Plus d''informations, mais des parents « aussi inquiets ».'),
  ('lo44cace32', 'lo44cade1ce', 32, 'qcm', 'Comment les agences tirent-elles parti de ce phénomène ?', '{"doc":"<p>La façon dont nous nous souvenons d''un voyage dépend moins de sa durée que de quelques moments marquants et de sa fin. Un séjour agréable qui s''achève sur un incident désagréable laissera un souvenir plus terne qu''un séjour moyen terminé en beauté. Les agences de voyages l''ont bien compris : elles soignent tout particulièrement le dernier jour.</p>","options":["En allongeant la durée des voyages.","En soignant la fin du séjour.","En multipliant les activités.","En baissant leurs prix."]}'::jsonb, '{"answer":1}'::jsonb, '« elles soignent tout particulièrement le dernier jour ».'),
  ('lo44cace33', 'lo44cade1ce', 33, 'qcm', 'Que reproche le critique à ce roman ?', '{"doc":"<p>Ce premier roman ne manque ni de souffle ni d''ambition. Mais l''auteur, visiblement soucieux de ne rien laisser dans l''ombre, explique tout : les motivations de ses personnages, leurs silences, jusqu''aux symboles qu''il dissémine dans le récit. Le lecteur, privé de toute part d''interprétation, finit par se sentir tenu par la main.</p>","options":["Il manque d''ambition.","Il laisse trop peu de place au lecteur.","Son style est trop obscur.","Ses personnages sont mal décrits."]}'::jsonb, '{"answer":1}'::jsonb, 'Le lecteur est « privé de toute part d''interprétation ».'),
  ('lo44cace34', 'lo44cade1ce', 34, 'qcm', 'Qu''est-ce qui inquiète surtout la chercheuse ?', '{"doc":"<p>La chercheuse en éducation aux médias s''alarme moins de la circulation des fausses nouvelles que de la réaction qu''elles suscitent. À force d''être mis en garde contre les manipulations, une partie du public en vient à se méfier de toute information, y compris des sources les plus fiables. Ce scepticisme généralisé, souligne-t-elle, profite paradoxalement à ceux qui propagent la désinformation.</p>","options":["Le manque d''esprit critique des jeunes.","L''absence de lois sur l''information.","Une méfiance qui s''étend à toutes les sources.","Le nombre croissant de fausses nouvelles."]}'::jsonb, '{"answer":2}'::jsonb, 'Le public finit par « se méfier de toute information ».'),
  ('lo44cace35', 'lo44cade1ce', 35, 'qcm', 'Sur quoi reposait la crainte des commerçants ?', '{"doc":"<p>Les villes qui ont réduit la place de la voiture dans leur centre n''ont pas connu l''effondrement commercial que redoutaient les commerçants. Les études montrent au contraire que les piétons et les cyclistes, s''ils dépensent moins à chaque passage, reviennent plus souvent. La crainte initiale reposait sur une surestimation systématique, par les commerçants eux-mêmes, de la part de leur clientèle venant en voiture.</p>","options":["Sur le prix du stationnement.","Sur des études défavorables.","Sur une baisse réelle de leurs ventes.","Sur une mauvaise évaluation de leur clientèle."]}'::jsonb, '{"answer":3}'::jsonb, 'Ils surestimaient « la part de leur clientèle venant en voiture ».'),
  ('lo44cace36', 'lo44cade1ce', 36, 'qcm', 'Quelle réserve l''auteur formule-t-il ?', '{"doc":"<p>On aurait tort de voir dans l''engouement pour la généalogie une simple curiosité de retraités. Dans des sociétés marquées par la mobilité et la dispersion des familles, la quête des ancêtres répond à un besoin d''inscription : savoir d''où l''on vient permet de conjurer le sentiment de n''appartenir à rien. Encore faut-il que cette recherche ne se mue pas en assignation, chacun se voyant réduit à une origine qu''il n''a pas choisie.</p>","options":["Les familles refusent de transmettre leur histoire.","La généalogie n''intéresse que les retraités.","La recherche des origines peut enfermer l''individu.","La mobilité rend la généalogie impossible."]}'::jsonb, '{"answer":2}'::jsonb, 'Il ne faut pas que la recherche devienne une « assignation » à une origine.'),
  ('lo44cace37', 'lo44cade1ce', 37, 'qcm', 'Que dénonce l''auteur ?', '{"doc":"<p>Il est tentant de mesurer la vitalité culturelle d''une ville au nombre de ses festivals. Cette comptabilité flatteuse masque pourtant une réalité plus contrastée : l''événementiel absorbe une part croissante des subventions, au détriment des lieux permanents, ateliers, salles de quartier, bibliothèques, qui font vivre la culture le reste de l''année, loin des projecteurs.</p>","options":["Le manque de festivals.","La fermeture des bibliothèques.","Un déséquilibre dans le financement de la culture.","Le désintérêt du public pour la culture."]}'::jsonb, '{"answer":2}'::jsonb, 'L''événementiel absorbe les subventions « au détriment des lieux permanents ».'),
  ('lo44cace38', 'lo44cade1ce', 38, 'qcm', 'Que soulignent les détracteurs de ce modèle ?', '{"doc":"<p>L''entreprise dite libérée, où les échelons hiérarchiques sont supprimés au profit de l''autonomie des équipes, a suscité un enthousiasme considérable. Ses détracteurs observent toutefois que la disparition des chefs ne fait pas disparaître le pouvoir : elle le rend simplement moins visible, et donc plus difficile à contester, lorsque des meneurs informels s''imposent sans en avoir le titre.</p>","options":["Les chefs sont devenus plus nombreux.","Ce modèle coûte trop cher.","Les équipes manquent d''autonomie.","Le pouvoir subsiste sous une forme moins visible."]}'::jsonb, '{"answer":3}'::jsonb, 'Le pouvoir devient « moins visible, et donc plus difficile à contester ».'),
  ('lo44cace39', 'lo44cade1ce', 39, 'qcm', 'Que soutient l''auteur à propos de la traduction ?', '{"doc":"<p>Toute traduction est une interprétation, et c''est précisément en cela qu''elle est féconde. Exiger d''elle une fidélité absolue, c''est méconnaître que les langues ne découpent pas le réel de la même manière : traduire un texte, ce n''est pas en reproduire les mots, mais en recréer les effets, au risque assumé de s''éloigner de la lettre pour rester fidèle à l''esprit.</p>","options":["Elle est impossible entre des langues éloignées.","Elle doit recréer l''effet du texte plutôt que ses mots.","Elle trahit toujours le texte original.","Elle doit rester fidèle mot à mot."]}'::jsonb, '{"answer":1}'::jsonb, 'Traduire, c''est « recréer les effets », pas « reproduire les mots ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44cade1pe', 'exam', 'TCF Canada · Đề 1 : Expression écrite', 'TCF', array['Production écrite']::text[], 'practice', null, 60, '<p><strong>Expression écrite : 60 minutes, 3 tâches.</strong> Respectez le nombre de mots demandé pour chaque tâche.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44cape1', 'lo44cade1pe', 1, 'open', 'Tâche 1 (60 mots minimum, 120 mots maximum)' || chr(10) || 'Vous venez de vous inscrire dans un club de sport de votre quartier. Écrivez un message à un(e) ami(e) pour lui proposer de vous accompagner. Précisez les jours, les horaires, les activités proposées et le prix.', '{}'::jsonb, '{}'::jsonb, null),
  ('lo44cape2', 'lo44cade1pe', 2, 'open', 'Tâche 2 (120 mots minimum, 150 mots maximum)' || chr(10) || 'Vous avez assisté à un spectacle de rue pendant un festival d''été. Sur votre blog, racontez cette soirée et expliquez ce qui vous a le plus marqué(e).', '{}'::jsonb, '{}'::jsonb, null),
  ('lo44cape3', 'lo44cade1pe', 3, 'open', 'Tâche 3 (120 mots minimum, 180 mots maximum)' || chr(10) || 'Faut-il autoriser les animaux de compagnie sur le lieu de travail ?' || chr(10) || '' || chr(10) || 'Document 1 : De plus en plus d''entreprises acceptent que leurs employés viennent avec leur chien. Selon plusieurs responsables, la présence d''un animal détend l''atmosphère, réduit le stress et encourage les pauses, ce qui améliore finalement la concentration. Certains salariés affirment même qu''ils se sentent plus attachés à leur entreprise.' || chr(10) || '' || chr(10) || 'Document 2 : Tout le monde n''apprécie pas les animaux. Allergies, peur des chiens, bruit pendant les réunions téléphoniques : la présence d''animaux au bureau peut devenir une source de conflits entre collègues. Sans règles claires, ce qui devait être un avantage risque de devenir une gêne pour une partie de l''équipe.' || chr(10) || '' || chr(10) || 'Vous écrivez un article pour le site d''un journal. Dans une première partie (40 à 60 mots), présentez les deux points de vue. Dans une seconde partie (80 à 120 mots), donnez votre opinion en l''illustrant d''exemples.', '{}'::jsonb, '{}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44cade1po', 'exam', 'TCF Canada · Đề 1 : Expression orale', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p><strong>Expression orale : 12 minutes environ, 3 tâches.</strong></p><p><strong>Tâche 1. Entretien dirigé</strong> (2 minutes, sans préparation) : présentez-vous. Parlez de vous, de votre famille, de votre travail ou de vos études, de vos loisirs, de vos projets au Canada.</p><p><strong>Tâche 2. Exercice en interaction</strong> (5 minutes 30, dont 2 minutes de préparation) : l''examinateur joue un rôle, vous lui posez des questions.</p><p><strong>Tâche 3. Expression d''un point de vue</strong> (4 minutes 30, sans préparation) : vous donnez votre opinion sur un sujet et vous la justifiez.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"bocTham":{"chuanBi":2,"phan":[{"ten":"Tâche 2. Exercice en interaction (5 min 30)","cachLam":"Posez des questions à l''examinateur pour obtenir les informations dont vous avez besoin.","soRut":1,"sujets":[{"ma":"1","html":"<p>Je suis votre voisin(e). Je fais du ski de fond tous les week-ends en hiver. Vous voulez essayer. Posez-moi des questions (lieu, équipement, prix, niveau, etc.).</p>"},{"ma":"2","html":"<p>Je travaille dans une école de langues. Vous voulez suivre des cours d''anglais le soir. Posez-moi des questions (horaires, groupes, tarifs, professeurs, etc.).</p>"},{"ma":"3","html":"<p>Je suis votre collègue. J''ai adopté un chien récemment. Vous hésitez à en adopter un. Posez-moi des questions (race, coût, temps, logement, etc.).</p>"},{"ma":"4","html":"<p>Je suis responsable du jardin communautaire de votre quartier. Vous voulez y cultiver une parcelle. Posez-moi des questions (inscription, règles, coût, etc.).</p>"}]},{"ten":"Tâche 3. Expression d''un point de vue (4 min 30)","cachLam":"Donnez votre opinion et justifiez-la avec des arguments et des exemples.","soRut":1,"sujets":[{"ma":"A","html":"<p>Selon vous, vaut-il mieux vivre en ville ou à la campagne ? Pourquoi ?</p>"},{"ma":"B","html":"<p>Les jeunes devraient-ils travailler pendant leurs études ? Donnez votre avis.</p>"},{"ma":"C","html":"<p>Faut-il limiter le temps que les enfants passent devant les écrans ?</p>"},{"ma":"D","html":"<p>Avec les outils de traduction automatique, est-il encore utile d''apprendre une langue étrangère ?</p>"}]}]}}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing;

