with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44tpde1co', 'exam', 'TCF Pháp · Đề 1 : Compréhension orale', 'TCF_TP', array['Écoute']::text[], 'practice', null, 25, '<p><strong>Compréhension orale : 29 questions, 25 minutes.</strong> Chaque document est diffusé <strong>une seule fois</strong> : lancez l''écoute de la question, puis choisissez la bonne réponse. Pour certaines questions, les propositions ne sont pas écrites : vous les entendez seulement.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44tpco01', 'lo44tpde1co', 1, 'qcm', 'Écoutez les quatre propositions. Choisissez celle qui correspond à l''image.', '{"anh":"https://ouch-prod-var-cdn.icons8.com/bi/illustrations/previews/KyegRyiXrYkcf-kl.webp","options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-01.mp3"}'::jsonb, '{"answer":2,"model":"A. Un homme répare son vélo. B. Un homme attend le bus. C. Un cycliste porte un casque. D. Un homme promène son chien."}'::jsonb, 'Sur l''image, l''homme roule à vélo avec un casque.'),
  ('lo44tpco02', 'lo44tpde1co', 2, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-02.mp3"}'::jsonb, '{"answer":0,"model":"Bonjour, une baguette, s''il vous plaît.\nA. Voilà, un euro dix. B. Il pleut ce matin. C. Je suis professeur. D. À la gare."}'::jsonb, 'À la boulangerie, la vendeuse donne le pain et annonce le prix.'),
  ('lo44tpco03', 'lo44tpde1co', 3, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-03.mp3"}'::jsonb, '{"answer":1,"model":"Tu habites où ?\nA. J''ai vingt ans. B. Dans le quinzième arrondissement. C. Avec plaisir. D. En voiture."}'::jsonb, 'La question porte sur le lieu d''habitation.'),
  ('lo44tpco04', 'lo44tpde1co', 4, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-04.mp3"}'::jsonb, '{"answer":2,"model":"Excusez-moi, le train pour Lyon part de quel quai ?\nA. Il coûte quarante euros. B. C''est un TGV. C. Voie sept, dans dix minutes. D. Je descends à Dijon."}'::jsonb, 'On demande le quai : la réponse donne la voie.'),
  ('lo44tpco05', 'lo44tpde1co', 5, 'qcm', 'Écoutez l''extrait sonore et les quatre propositions. Choisissez la bonne réponse.', '{"options":["","","",""],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-05.mp3"}'::jsonb, '{"answer":1,"model":"On se retrouve devant le cinéma à vingt heures ?\nA. Le film est américain. B. Plutôt vingt heures trente, je finis tard. C. J''ai vu ce film hier. D. Le cinéma est fermé le lundi."}'::jsonb, 'On propose un rendez-vous : la réponse propose une autre heure.'),
  ('lo44tpco06', 'lo44tpde1co', 6, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Le train part plus tôt.","Le train part en retard.","Le train change de quai.","Le train est annulé."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-06.mp3"}'::jsonb, '{"answer":1,"model":"Mesdames et messieurs, le TER à destination de Rouen, prévu à quatorze heures douze, partira avec un retard d''environ vingt minutes en raison d''un incident technique.\nQue se passe-t-il ?"}'::jsonb, '« partira avec un retard d''environ vingt minutes ».'),
  ('lo44tpco07', 'lo44tpde1co', 7, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["D''annuler la réunion.","D''appeler le médecin.","De garder sa fille.","De noter les informations de la réunion."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-07.mp3"}'::jsonb, '{"answer":3,"model":"Salut, c''est Sophie. Je ne pourrai pas venir à la réunion des parents ce soir, ma fille est malade. Est-ce que tu peux prendre des notes pour moi ?\nQue demande Sophie ?"}'::jsonb, '« Est-ce que tu peux prendre des notes pour moi ? »'),
  ('lo44tpco08', 'lo44tpde1co', 8, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Une pièce d''identité.","L''emballage d''origine.","Le ticket de caisse.","Une carte de fidélité."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-08.mp3"}'::jsonb, '{"answer":2,"model":"Bonjour, je voudrais échanger ce pull, il est trop petit.\nVous avez le ticket de caisse ? Sans ticket, je ne peux pas faire l''échange.\nQu''est-ce qui est nécessaire pour échanger le pull ?"}'::jsonb, '« Sans ticket, je ne peux pas faire l''échange ».'),
  ('lo44tpco09', 'lo44tpde1co', 9, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Pour diminuer le nombre de voitures en ville.","Pour fêter une nouvelle ligne.","Pour attirer les touristes.","Pour aider les commerçants du marché."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-09.mp3"}'::jsonb, '{"answer":0,"model":"À partir du premier mars, les bus de la ville seront gratuits le samedi pour tous les habitants. La mairie espère ainsi réduire la circulation automobile dans le centre-ville les jours de marché.\nPourquoi la mairie rend-elle les bus gratuits le samedi ?"}'::jsonb, 'Elle espère « réduire la circulation automobile ».'),
  ('lo44tpco10', 'lo44tpde1co', 10, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["À cause du climat.","Pour partir avec sa famille.","Pour terminer un travail.","Pour payer moins cher."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-10.mp3"}'::jsonb, '{"answer":2,"model":"Tu pars en vacances quand, finalement ?\nNormalement en août. Mais mon chef me demande de rester jusqu''à la fin du projet, alors je vais sûrement décaler à septembre.\nPourquoi la femme va-t-elle changer ses dates de vacances ?"}'::jsonb, 'Son chef lui demande de rester « jusqu''à la fin du projet ».'),
  ('lo44tpco11', 'lo44tpde1co', 11, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Une autre salle.","Une autre date.","Un repas d''équipe.","Une réunion en ligne."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-11.mp3"}'::jsonb, '{"answer":0,"model":"Bonjour Monsieur Lefèvre, la salle de réunion que vous aviez réservée pour jeudi est en travaux. Je vous propose la salle deux cent quatre, au deuxième étage, qui peut accueillir le même nombre de personnes.\nQue propose la personne ?"}'::jsonb, 'Elle propose « la salle deux cent quatre ».'),
  ('lo44tpco12', 'lo44tpde1co', 12, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Apprendre les mouvements.","Vaincre sa peur.","Trouver une piscine.","Trouver du temps."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-12.mp3"}'::jsonb, '{"answer":1,"model":"J''ai appris à nager à quarante ans. Je n''avais pas honte, mais je pensais que c''était trop tard. En fait, le plus difficile n''a pas été la technique : ça a été de surmonter ma peur de l''eau.\nQu''est-ce qui a été le plus difficile pour cette femme ?"}'::jsonb, '« le plus difficile… ça a été de surmonter ma peur de l''eau ».'),
  ('lo44tpco13', 'lo44tpde1co', 13, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Aux étudiants.","Aux enfants.","Aux personnes âgées.","Aux familles nombreuses."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-13.mp3"}'::jsonb, '{"answer":2,"model":"La médiathèque propose désormais des ateliers numériques pour les seniors : envoyer un courriel, faire une démarche administrative en ligne, partager des photos avec sa famille. Les ateliers sont gratuits, mais le nombre de places est limité.\nÀ qui s''adressent ces ateliers ?"}'::jsonb, 'Ateliers « pour les seniors ».'),
  ('lo44tpco14', 'lo44tpde1co', 14, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["La petite surface.","Le prix du loyer.","Le manque de lumière.","L''accès difficile."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-14.mp3"}'::jsonb, '{"answer":3,"model":"L''appartement est très lumineux, mais il n''y a pas d''ascenseur, et c''est au cinquième étage.\nAh… Avec la poussette du bébé, ça risque d''être compliqué.\nQuel problème pose l''appartement pour la femme ?"}'::jsonb, 'Cinquième étage sans ascenseur, avec une poussette.'),
  ('lo44tpco15', 'lo44tpde1co', 15, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Des touristes.","Des sportifs de haut niveau.","Des étudiants.","Des personnes qui habitent loin de leur travail."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-15.mp3"}'::jsonb, '{"answer":3,"model":"Les ventes de vélos à assistance électrique ont doublé en trois ans. Les acheteurs sont souvent des personnes qui habitent à plus de dix kilomètres de leur travail et qui veulent éviter les embouteillages.\nQui achète surtout ces vélos ?"}'::jsonb, 'Personnes « qui habitent à plus de dix kilomètres de leur travail ».'),
  ('lo44tpco16', 'lo44tpde1co', 16, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Pour attirer des touristes.","Pour gagner de l''argent.","Pour loger des habitants.","Pour garder un lieu de rencontre."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-16.mp3"}'::jsonb, '{"answer":3,"model":"De plus en plus de communes rurales rachètent le dernier café du village pour éviter sa fermeture. Pour les élus, il ne s''agit pas de faire du commerce, mais de préserver un lieu où les habitants se croisent et échangent des nouvelles.\nPourquoi les communes rachètent-elles ces cafés ?"}'::jsonb, '« préserver un lieu où les habitants se croisent ».'),
  ('lo44tpco17', 'lo44tpde1co', 17, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Arrêter de jardiner en ville.","Planter loin des écoles.","Faire vérifier la qualité du sol.","Utiliser davantage d''engrais."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-17.mp3"}'::jsonb, '{"answer":2,"model":"Le jardinage urbain est à la mode. Mais attention : cultiver des légumes au bord d''une route très fréquentée n''est pas sans risque. Les spécialistes recommandent de faire analyser la terre et de laver soigneusement les récoltes.\nQue conseillent les spécialistes ?"}'::jsonb, '« faire analyser la terre ».'),
  ('lo44tpco18', 'lo44tpde1co', 18, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les parents sont seuls responsables.","L''interdiction ne suffit pas sans éducation.","Les élèves utilisent peu leur téléphone.","Il faut autoriser les téléphones."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-18.mp3"}'::jsonb, '{"answer":1,"model":"Faut-il interdire les téléphones portables au collège ?\nJ''y suis plutôt favorable. Mais l''interdiction ne réglera rien si on n''apprend pas aussi aux élèves à s''en servir de façon raisonnable, y compris à la maison.\nQuel est l''avis de l''homme ?"}'::jsonb, '« l''interdiction ne réglera rien si on n''apprend pas… ».'),
  ('lo44tpco19', 'lo44tpde1co', 19, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Attirer de nouveaux clients.","Rapprocher des collègues de services différents.","Réduire les absences.","Augmenter la productivité."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-19.mp3"}'::jsonb, '{"answer":1,"model":"Dans cette entreprise lyonnaise, les salariés peuvent venir au bureau avec leur chien. Selon la direction, la mesure a réduit le stress, mais elle a surtout eu un effet inattendu : des collègues de services différents, qui ne se parlaient presque jamais, discutent désormais pendant les promenades.\nQuel effet inattendu la mesure a-t-elle eu ?"}'::jsonb, 'Des collègues « qui ne se parlaient presque jamais » discutent.'),
  ('lo44tpco20', 'lo44tpde1co', 20, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["En s''installant plus au nord.","En arrêtant le vin rouge.","En choisissant d''autres variétés de vigne.","En vendangeant plus tard."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-20.mp3"}'::jsonb, '{"answer":2,"model":"Je suis viticultrice depuis vingt ans. Avec le réchauffement, nous vendangeons trois semaines plus tôt qu''autrefois. Certains collègues plantent déjà des cépages venus du sud de l''Europe, plus résistants à la chaleur.\nComment certains viticulteurs s''adaptent-ils ?"}'::jsonb, 'Ils plantent « des cépages venus du sud de l''Europe ».'),
  ('lo44tpco21', 'lo44tpde1co', 21, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Les bouteilles cassent facilement.","Les clients refusent de payer plus.","Il faut organiser la collecte et le lavage.","Le verre est trop cher."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-21.mp3"}'::jsonb, '{"answer":2,"model":"La consigne des bouteilles en verre fait son retour dans plusieurs régions. Le client paie quelques centimes de plus, qu''il récupère en rapportant la bouteille, qui sera lavée et réutilisée. Les industriels restent prudents : il faut créer des circuits de collecte et de lavage qui n''existent plus.\nPourquoi les industriels restent-ils prudents ?"}'::jsonb, 'Il faut « créer des circuits de collecte et de lavage ».'),
  ('lo44tpco22', 'lo44tpde1co', 22, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["La possibilité de faire un stage.","La réputation de l''université.","La ville d''études.","Le coût des études."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-22.mp3"}'::jsonb, '{"answer":0,"model":"Tu as choisi ton master ?\nJ''hésite entre un master très réputé à Paris et un autre, moins connu, à Nantes, mais avec un stage garanti en entreprise. Je crois que l''expérience concrète compte plus que le nom de l''université.\nQu''est-ce qui oriente le choix de l''étudiant ?"}'::jsonb, '« l''expérience concrète compte plus que le nom ».'),
  ('lo44tpco23', 'lo44tpde1co', 23, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["L''écran nuit toujours à la compréhension.","Le papier reste préférable pour les textes complexes.","Le papier n''a aucun avantage.","Les textes courts se lisent mieux sur papier."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-23.mp3"}'::jsonb, '{"answer":1,"model":"On présente souvent la lecture sur écran comme l''ennemie du livre. Les études sont plus nuancées : pour des textes courts, la compréhension est équivalente. C''est sur les textes longs et complexes que le papier conserve un avantage, sans doute parce qu''il favorise une lecture plus lente et un meilleur repérage dans le texte.\nQue montrent les études ?"}'::jsonb, 'Le papier garde un avantage « sur les textes longs et complexes ».'),
  ('lo44tpco24', 'lo44tpde1co', 24, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Parce que les départs semblent volontaires.","Parce que la loi l''encourage.","Parce que les habitants l''approuvent.","Parce qu''il est très rapide."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-24.mp3"}'::jsonb, '{"answer":0,"model":"La gentrification de ce quartier ne s''est pas faite par la force, mais par petites touches : un café branché, une galerie, puis des loyers qui augmentent. Les anciens habitants ne sont pas expulsés ; ils partent d''eux-mêmes, faute de pouvoir suivre. Et c''est précisément ce qui rend le phénomène si difficile à combattre.\nPourquoi ce phénomène est-il difficile à combattre ?"}'::jsonb, 'Les habitants « partent d''eux-mêmes ».'),
  ('lo44tpco25', 'lo44tpde1co', 25, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Financer la recherche.","Sensibiliser le public.","Réintroduire des espèces menacées.","Soigner les animaux blessés."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-25.mp3"}'::jsonb, '{"answer":1,"model":"Les zoos se présentent volontiers comme des arches de Noé modernes. Pourtant, rares sont les espèces réellement réintroduites dans la nature grâce à eux. Leur rôle principal reste l''éducation du public, ce qui n''est pas négligeable, à condition de ne pas le confondre avec la sauvegarde de la biodiversité.\nQuel est, selon l''intervenant, le rôle principal des zoos ?"}'::jsonb, '« Leur rôle principal reste l''éducation du public ».'),
  ('lo44tpco26', 'lo44tpde1co', 26, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Ils stockent davantage de produits.","Ils disparaissent progressivement.","Ils servent surtout à découvrir les produits.","Ils vendent moins cher qu''en ligne."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-26.mp3"}'::jsonb, '{"answer":2,"model":"L''essor du commerce en ligne n''a pas fait disparaître les magasins physiques ; il en a transformé la fonction. Ils deviennent des vitrines où l''on vient voir, toucher, essayer, avant de commander ailleurs. Les enseignes qui l''ont compris réduisent leurs stocks et misent sur le conseil.\nComment la fonction des magasins a-t-elle changé ?"}'::jsonb, 'Ils deviennent « des vitrines où l''on vient voir, toucher, essayer ».'),
  ('lo44tpco27', 'lo44tpde1co', 27, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Ils protègent de l''isolement.","Ils remplacent la famille.","Ils poussent les jeunes à partir.","Ils donnent une impression trompeuse de compagnie."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-27.mp3"}'::jsonb, '{"answer":3,"model":"Contrairement à ce que l''on croit, la solitude touche fortement les jeunes adultes, notamment ceux qui viennent de quitter le domicile familial pour leurs études. Les réseaux sociaux donnent l''illusion d''un entourage nombreux, sans offrir la qualité de relation qui protège réellement de l''isolement.\nQue dit-on des réseaux sociaux ?"}'::jsonb, 'Ils « donnent l''illusion d''un entourage nombreux ».'),
  ('lo44tpco28', 'lo44tpde1co', 28, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Elle empêche d''être sincère.","Elle marque les différences sociales.","Elle est une tradition dépassée.","Elle facilite et apaise les relations."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-28.mp3"}'::jsonb, '{"answer":3,"model":"On aurait tort de réduire la politesse à un ensemble de conventions désuètes. Elle constitue une forme d''économie des relations : en ritualisant les échanges, elle épargne à chacun l''effort de renégocier sans cesse la distance qui convient, et désamorce bien des conflits avant même qu''ils n''éclatent.\nQuelle fonction l''intervenant attribue-t-il à la politesse ?"}'::jsonb, 'Elle « désamorce bien des conflits ».'),
  ('lo44tpco29', 'lo44tpde1co', 29, 'qcm', 'Écoutez le document sonore et la question. Choisissez la bonne réponse.', '{"options":["Il faut démolir les bâtiments anciens.","Les villes doivent s''étendre.","Les matériaux écologiques suffisent.","Il vaut mieux transformer l''existant que construire."],"audio":"https://cdszvnuaibnnkrvynyck.supabase.co/storage/v1/object/public/nghe/tcf-tp-de1-co-29.mp3"}'::jsonb, '{"answer":3,"model":"Cet architecte défend une idée à rebours de son époque : construire moins. Plutôt que de bâtir du neuf, il plaide pour la transformation de l''existant, bureaux vides, entrepôts, casernes, convaincu que le bâtiment le plus écologique est celui que l''on n''a pas besoin de construire.\nQuelle conviction l''architecte exprime-t-il ?"}'::jsonb, '« le bâtiment le plus écologique est celui que l''on n''a pas besoin de construire ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44tpde1ms', 'exam', 'TCF Pháp · Đề 1 : Maîtrise des structures de la langue', 'TCF_TP', array['Grammaire']::text[], 'practice', null, 15, '<p><strong>Maîtrise des structures de la langue : 18 questions, 15 minutes.</strong> Choisissez le mot ou l''expression qui complète correctement chaque phrase.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44tpms01', 'lo44tpde1ms', 1, 'qcm', 'Nous ____ français à la maison.', '{"options":["parle","parlent","parlez","parlons"]}'::jsonb, '{"answer":3}'::jsonb, 'Avec « nous », le verbe se termine par -ons.'),
  ('lo44tpms02', 'lo44tpde1ms', 2, 'qcm', 'J''habite ____ Marseille depuis deux ans.', '{"options":["dans","au","à","en"]}'::jsonb, '{"answer":2}'::jsonb, 'On utilise « à » devant un nom de ville.'),
  ('lo44tpms03', 'lo44tpde1ms', 3, 'qcm', 'Hier, elle ____ au cinéma avec ses amies.', '{"options":["est allée","allait aller","a allé","va"]}'::jsonb, '{"answer":0}'::jsonb, '« Aller » se conjugue avec « être » au passé composé, accordé au féminin.'),
  ('lo44tpms04', 'lo44tpde1ms', 4, 'qcm', 'Tu as vu Marie ? Oui, je ____ ai vue hier.', '{"options":["lui","la","le","l''"]}'::jsonb, '{"answer":3}'::jsonb, 'Complément d''objet direct féminin devant une voyelle : « l'' ».'),
  ('lo44tpms05', 'lo44tpde1ms', 5, 'qcm', 'Quand j''étais petit, je ____ à la campagne.', '{"options":["ai vécu","vis","vivais","vivrai"]}'::jsonb, '{"answer":2}'::jsonb, 'L''imparfait exprime une habitude ou une situation dans le passé.'),
  ('lo44tpms06', 'lo44tpde1ms', 6, 'qcm', 'C''est le livre ____ je t''ai parlé hier.', '{"options":["que","dont","lequel","où"]}'::jsonb, '{"answer":1}'::jsonb, '« Parler de » : le pronom relatif est « dont ».'),
  ('lo44tpms07', 'lo44tpde1ms', 7, 'qcm', 'Si j''avais plus de temps, je ____ plus souvent.', '{"options":["voyagerais","voyage","voyagerai","voyageais"]}'::jsonb, '{"answer":0}'::jsonb, 'Si + imparfait, conditionnel présent.'),
  ('lo44tpms08', 'lo44tpde1ms', 8, 'qcm', 'Il faut que tu ____ tes papiers avant lundi.', '{"options":["fasses","faisais","fais","feras"]}'::jsonb, '{"answer":0}'::jsonb, '« Il faut que » est suivi du subjonctif.'),
  ('lo44tpms09', 'lo44tpde1ms', 9, 'qcm', 'Elle a réussi l''examen ____ elle n''avait pas beaucoup révisé.', '{"options":["afin qu''","alors qu''","puisqu''","parce qu''"]}'::jsonb, '{"answer":1}'::jsonb, '« Alors que » exprime une opposition.'),
  ('lo44tpms10', 'lo44tpde1ms', 10, 'qcm', 'Je regrette qu''il ____ partir si tôt hier soir.', '{"options":["ait dû","devra","devait","a dû"]}'::jsonb, '{"answer":0}'::jsonb, '« Regretter que » demande le subjonctif ; l''action est passée : subjonctif passé.'),
  ('lo44tpms11', 'lo44tpde1ms', 11, 'qcm', '____ la pluie, le match a été maintenu.', '{"options":["Bien que","Grâce à","Malgré","Pourtant"]}'::jsonb, '{"answer":2}'::jsonb, '« Malgré » est suivi d''un nom et exprime la concession.'),
  ('lo44tpms12', 'lo44tpde1ms', 12, 'qcm', 'Les documents ____ vous m''avez envoyés sont incomplets.', '{"options":["lesquels","que","dont","qui"]}'::jsonb, '{"answer":1}'::jsonb, '« Envoyer quelque chose » : complément direct, pronom « que ».'),
  ('lo44tpms13', 'lo44tpde1ms', 13, 'qcm', 'Il m''a demandé si je ____ venir le lendemain.', '{"options":["pourrai","pouvais","peux","puisse"]}'::jsonb, '{"answer":1}'::jsonb, 'Discours indirect au passé : le présent devient imparfait.'),
  ('lo44tpms14', 'lo44tpde1ms', 14, 'qcm', 'Une fois les travaux ____, nous emménagerons.', '{"options":["terminés","terminer","terminant","termineront"]}'::jsonb, '{"answer":0}'::jsonb, '« Une fois » + participe passé accordé avec le nom.'),
  ('lo44tpms15', 'lo44tpde1ms', 15, 'qcm', 'Il est parti sans que personne ne s''en ____ compte.', '{"options":["rendra","rendait","rend","rende"]}'::jsonb, '{"answer":3}'::jsonb, '« Sans que » est suivi du subjonctif.'),
  ('lo44tpms16', 'lo44tpde1ms', 16, 'qcm', '____ soient ses arguments, il ne me convaincra pas.', '{"options":["Quelques","Quels que","Quoique","Quel que"]}'::jsonb, '{"answer":1}'::jsonb, '« Quel que » + être au subjonctif, accordé avec « arguments » (masculin pluriel).'),
  ('lo44tpms17', 'lo44tpde1ms', 17, 'qcm', 'Le projet ____ on avait tant parlé a finalement été abandonné.', '{"options":["où","auquel","lequel","dont"]}'::jsonb, '{"answer":3}'::jsonb, '« Parler d''un projet » : « dont ».'),
  ('lo44tpms18', 'lo44tpde1ms', 18, 'qcm', 'Pour peu qu''il ____ le moindre effort, il réussirait.', '{"options":["fasse","fait","a fait","ferait"]}'::jsonb, '{"answer":0}'::jsonb, '« Pour peu que » exprime une condition minimale et est suivi du subjonctif.')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44tpde1ce', 'exam', 'TCF Pháp · Đề 1 : Compréhension écrite', 'TCF_TP', array['Lecture']::text[], 'practice', null, 45, '<p><strong>Compréhension écrite : 29 questions, 45 minutes.</strong> Lisez chaque document, puis choisissez la bonne réponse.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44tpce01', 'lo44tpde1ce', 1, 'qcm', 'Où est Emma ?', '{"doc":"<p>Chère Julie,</p><p>Je suis à la plage avec mes parents. Il fait beau et chaud. Je rentre dimanche.</p><p>Bisous, Emma</p>","options":["À la maison.","À l''école.","Au bord de la mer.","À la montagne."]}'::jsonb, '{"answer":2}'::jsonb, '« Je suis à la plage ».'),
  ('lo44tpce02', 'lo44tpde1ce', 2, 'qcm', 'Quel jour la boulangerie est-elle fermée ?', '{"doc":"<p><strong>Boulangerie Martin</strong></p><p>Ouvert de 7 h à 19 h.</p><p>Fermé le mercredi.</p>","options":["Le lundi.","Le mercredi.","Le dimanche.","Le samedi."]}'::jsonb, '{"answer":1}'::jsonb, '« Fermé le mercredi ».'),
  ('lo44tpce03', 'lo44tpde1ce', 3, 'qcm', 'Que fait Léo ce soir ?', '{"doc":"<p>Maman,</p><p>Je mange chez Lucas ce soir. Je rentre à 21 h.</p><p>Léo</p>","options":["Il fait du sport.","Il va au restaurant.","Il dîne chez un ami.","Il reste à la maison."]}'::jsonb, '{"answer":2}'::jsonb, '« Je mange chez Lucas ».'),
  ('lo44tpce04', 'lo44tpde1ce', 4, 'qcm', 'Pourquoi Karine écrit-elle ?', '{"doc":"<p>Bonjour,</p><p>Je voudrais réserver une table pour quatre personnes samedi soir à 20 h. C''est pour l''anniversaire de mon père. Pouvez-vous me confirmer ?</p><p>Merci, Karine Dubois</p>","options":["Pour inviter son père.","Pour annuler une réservation.","Pour commander un gâteau.","Pour réserver un repas."]}'::jsonb, '{"answer":3}'::jsonb, '« Je voudrais réserver une table ».'),
  ('lo44tpce05', 'lo44tpde1ce', 5, 'qcm', 'Qu''est-ce qui est interdit ?', '{"doc":"<p><strong>Mairie de Villeneuve : collecte des encombrants</strong></p><p>Jeudi 6 juin. Déposez vos vieux meubles devant votre immeuble la veille au soir.</p><p>Les appareils électriques ne sont pas acceptés.</p>","options":["Sortir les objets le mercredi soir.","Déposer des meubles.","Déposer les objets devant l''immeuble.","Déposer des appareils électriques."]}'::jsonb, '{"answer":3}'::jsonb, '« Les appareils électriques ne sont pas acceptés ».'),
  ('lo44tpce06', 'lo44tpde1ce', 6, 'qcm', 'Que demande Inès à Nora ?', '{"doc":"<p>Salut Nora,</p><p>Je ne peux pas venir au cours de danse mardi : j''ai un rendez-vous chez le dentiste. Tu peux le dire au professeur ? Merci !</p><p>Inès</p>","options":["De prévenir le professeur.","De danser avec elle.","De l''accompagner chez le dentiste.","De changer de cours."]}'::jsonb, '{"answer":0}'::jsonb, '« Tu peux le dire au professeur ? »'),
  ('lo44tpce07', 'lo44tpde1ce', 7, 'qcm', 'Que doit faire la baby-sitter ?', '{"doc":"<p><strong>Cherche baby-sitter</strong></p><p>Pour deux enfants (5 et 8 ans), le mercredi après-midi, à Montpellier centre.</p><p>Aller chercher les enfants à l''école et les aider à faire leurs devoirs. 12 € de l''heure.</p>","options":["Faire le ménage.","Garder les enfants le soir.","Préparer le dîner.","Aller chercher les enfants et les aider pour les devoirs."]}'::jsonb, '{"answer":3}'::jsonb, '« Aller chercher les enfants à l''école et les aider à faire leurs devoirs ».'),
  ('lo44tpce08', 'lo44tpde1ce', 8, 'qcm', 'Que se passera-t-il mardi matin ?', '{"doc":"<p>Chers résidents,</p><p>L''eau sera coupée mardi de 9 h à 12 h pour des travaux dans l''immeuble. Pensez à faire des réserves.</p><p>Le gardien</p>","options":["Il n''y aura pas d''eau.","L''ascenseur sera en panne.","Il n''y aura pas d''électricité.","Le gardien sera absent."]}'::jsonb, '{"answer":0}'::jsonb, '« L''eau sera coupée mardi de 9 h à 12 h ».'),
  ('lo44tpce09', 'lo44tpde1ce', 9, 'qcm', 'Qu''est-ce qui est inclus dans le prix ?', '{"doc":"<p>La ville de Bordeaux lance un service de location de vélos à la journée pour les touristes. Les vélos sont disponibles dans dix stations proches des monuments. Le tarif comprend un casque et une carte des pistes cyclables.</p>","options":["Une assurance.","Un guide touristique.","L''entrée des monuments.","Un casque et une carte."]}'::jsonb, '{"answer":3}'::jsonb, '« Le tarif comprend un casque et une carte ».'),
  ('lo44tpce10', 'lo44tpde1ce', 10, 'qcm', 'Que va faire l''entreprise ?', '{"doc":"<p>Madame, Monsieur,</p><p>Suite à votre réclamation, nous vous informons que votre facture d''électricité du mois de mars contenait une erreur. Le montant payé en trop, soit 45 euros, sera déduit de votre prochaine facture.</p><p>Le service clients</p>","options":["Rembourser par chèque.","Réduire la prochaine facture.","Changer le compteur.","Annuler le contrat."]}'::jsonb, '{"answer":1}'::jsonb, 'Le trop-payé « sera déduit de votre prochaine facture ».'),
  ('lo44tpce11', 'lo44tpde1ce', 11, 'qcm', 'Que doivent faire les bénévoles avant de commencer ?', '{"doc":"<p>L''association Les Amis du livre recherche des bénévoles pour lire des histoires aux enfants hospitalisés, une heure par semaine. Aucune expérience n''est demandée, mais une formation de deux heures est obligatoire avant de commencer.</p>","options":["Écrire des histoires.","Avoir de l''expérience.","Travailler à l''hôpital.","Suivre une formation."]}'::jsonb, '{"answer":3}'::jsonb, '« une formation de deux heures est obligatoire ».'),
  ('lo44tpce12', 'lo44tpde1ce', 12, 'qcm', 'Où Hélène passe-t-elle ses vacances ?', '{"doc":"<p>Chère Valérie,</p><p>Nous voulions passer nos vacances en Bretagne, mais la maison que nous avions louée a été endommagée par une tempête. Le propriétaire nous a proposé un autre logement en Normandie, où nous sommes depuis lundi. Nous irons peut-être en Bretagne à la Toussaint.</p><p>Je t''embrasse, Hélène</p>","options":["Chez Valérie.","En Bretagne.","En Normandie.","Chez le propriétaire."]}'::jsonb, '{"answer":2}'::jsonb, '« un autre logement en Normandie, où nous sommes depuis lundi ».'),
  ('lo44tpce13', 'lo44tpde1ce', 13, 'qcm', 'Qu''observent les professeurs ?', '{"doc":"<p>Le collège Jean-Moulin teste cette année la « journée sans cartable » : un vendredi par mois, les élèves participent à des ateliers (théâtre, jardinage, sciences) au lieu des cours habituels. Les professeurs remarquent que certains élèves en difficulté se révèlent dans ces activités.</p>","options":["Les notes augmentent.","Les élèves sont moins fatigués.","Des élèves en difficulté montrent d''autres talents.","Les parents participent davantage."]}'::jsonb, '{"answer":2}'::jsonb, 'Certains élèves en difficulté « se révèlent ».'),
  ('lo44tpce14', 'lo44tpde1ce', 14, 'qcm', 'Que propose le camping ?', '{"doc":"<p><strong>Camping Les Pins : règlement</strong></p><p>Les barbecues sont interdits dans tout le camping en raison du risque d''incendie.</p><p>Un espace de cuisine collective est à votre disposition près de l''accueil.</p>","options":["Des repas livrés.","Un restaurant.","Des barbecues électriques.","Un lieu commun pour cuisiner."]}'::jsonb, '{"answer":3}'::jsonb, '« Un espace de cuisine collective est à votre disposition ».'),
  ('lo44tpce15', 'lo44tpde1ce', 15, 'qcm', 'Que révèle ce sondage ?', '{"doc":"<p>Selon un sondage, 60 % des Français disent faire attention à l''origine des produits qu''ils achètent. Mais au moment de passer en caisse, le prix reste le premier critère de choix pour la majorité d''entre eux.</p>","options":["L''origine des produits ne les intéresse pas.","Les Français achètent surtout des produits locaux.","Les produits locaux sont moins chers.","Le prix compte plus que l''origine au moment d''acheter."]}'::jsonb, '{"answer":3}'::jsonb, '« le prix reste le premier critère de choix ».'),
  ('lo44tpce16', 'lo44tpde1ce', 16, 'qcm', 'Quelle est la principale fragilité de ces librairies ?', '{"doc":"<p>Les librairies indépendantes résistent mieux que prévu à la concurrence des grandes plateformes. Leur atout : le conseil personnalisé et l''organisation de rencontres avec des auteurs, qui transforment la boutique en lieu de vie. Leur fragilité demeure cependant économique, la marge réalisée sur un livre restant très faible.</p>","options":["Le désintérêt des auteurs.","Le manque de conseils.","Leur faible rentabilité.","L''absence de clients."]}'::jsonb, '{"answer":2}'::jsonb, '« la marge réalisée sur un livre restant très faible ».'),
  ('lo44tpce17', 'lo44tpde1ce', 17, 'qcm', 'Quel argument avancent les opposants au redoublement ?', '{"doc":"<p>Faut-il supprimer le redoublement ? Ses partisans y voient une seconde chance. Ses opposants rappellent que les études montrent rarement un bénéfice durable, et soulignent le coût, pour l''élève, de la séparation d''avec ses camarades.</p>","options":["Il coûte cher à l''État.","Ses effets positifs sont rarement durables.","Les élèves le refusent.","Les professeurs ne l''appliquent pas."]}'::jsonb, '{"answer":1}'::jsonb, '« les études montrent rarement un bénéfice durable ».'),
  ('lo44tpce18', 'lo44tpde1ce', 18, 'qcm', 'Qui est surtout intéressé par ce service ?', '{"doc":"<p>Depuis le début de l''année, une jeune entreprise nantaise propose de louer des vêtements pour enfants plutôt que de les acheter. Les parents reçoivent un colis adapté à la taille de l''enfant et le renvoient quand celui-ci a grandi. Le service séduit surtout les familles soucieuses de réduire leurs déchets.</p>","options":["Les familles qui veulent limiter les déchets.","Les parents pressés.","Les familles nombreuses.","Les familles aisées."]}'::jsonb, '{"answer":0}'::jsonb, 'Il séduit « les familles soucieuses de réduire leurs déchets ».'),
  ('lo44tpce19', 'lo44tpde1ce', 19, 'qcm', 'Comment l''agence justifie-t-elle la fermeture ?', '{"doc":"<p>La fermeture de la maternité de cette petite ville inquiète les habitants : les futures mères devront désormais faire une heure de route pour accoucher. L''agence régionale de santé justifie sa décision par le faible nombre de naissances et le manque de médecins spécialistes.</p>","options":["Par l''ouverture d''un nouvel hôpital.","Par le manque d''activité et de spécialistes.","Par le coût des travaux.","Par la demande des habitants."]}'::jsonb, '{"answer":1}'::jsonb, '« le faible nombre de naissances et le manque de médecins spécialistes ».'),
  ('lo44tpce20', 'lo44tpde1ce', 20, 'qcm', 'Pourquoi l''accès à la plage est-il limité ?', '{"doc":"<p>Le tourisme de masse menace certains sites naturels. Dans les calanques près de Marseille, l''accès à une plage très fréquentée est désormais limité en été grâce à un système de réservation gratuite en ligne. L''objectif n''est pas de faire payer les visiteurs, mais de protéger une végétation piétinée chaque été.</p>","options":["Pour la sécurité des baigneurs.","Pour préserver la nature.","Pour réduire le bruit.","Pour gagner de l''argent."]}'::jsonb, '{"answer":1}'::jsonb, '« protéger une végétation piétinée ».'),
  ('lo44tpce21', 'lo44tpde1ce', 21, 'qcm', 'Que craignent les recruteurs ?', '{"doc":"<p>Les entreprises qui recrutent des seniors constatent souvent une meilleure stabilité de leurs équipes. Pourtant, après cinquante-cinq ans, retrouver un emploi reste difficile : les recruteurs craignent, à tort selon de nombreuses études, un manque d''adaptation aux nouvelles technologies.</p>","options":["Que les seniors coûtent trop cher.","Qu''ils soient souvent malades.","Que les seniors maîtrisent mal les outils numériques.","Qu''ils restent peu de temps dans l''entreprise."]}'::jsonb, '{"answer":2}'::jsonb, '« un manque d''adaptation aux nouvelles technologies ».'),
  ('lo44tpce22', 'lo44tpde1ce', 22, 'qcm', 'Que regrettent certains clients ?', '{"doc":"<p>La généralisation des caisses automatiques dans les supermarchés divise. Les enseignes mettent en avant la rapidité ; les syndicats dénoncent la suppression d''emplois ; et certains clients, notamment âgés, regrettent la disparition d''un contact humain parfois unique dans leur journée.</p>","options":["La lenteur des caisses.","La fermeture des magasins.","La perte d''échanges humains.","La hausse des prix."]}'::jsonb, '{"answer":2}'::jsonb, 'La disparition d''« un contact humain ».'),
  ('lo44tpce23', 'lo44tpde1ce', 23, 'qcm', 'Que conclut le texte sur les révisions de nuit ?', '{"doc":"<p>Les neurosciences ont mis en évidence l''importance du sommeil dans la consolidation des apprentissages. Pendant la nuit, le cerveau rejoue en quelque sorte les informations de la journée et trie ce qui mérite d''être conservé. Réviser toute la nuit avant un examen apparaît dès lors comme une stratégie contre-productive.</p>","options":["Elles sont indispensables.","Elles sont efficaces la veille d''un examen.","Elles améliorent le sommeil.","Elles nuisent à la mémorisation."]}'::jsonb, '{"answer":3}'::jsonb, 'Stratégie « contre-productive » : le sommeil consolide les apprentissages.'),
  ('lo44tpce24', 'lo44tpde1ce', 24, 'qcm', 'Quel bénéfice attribue-t-on à la médiation animale ?', '{"doc":"<p>La médiation animale se développe dans les établissements pour personnes âgées. La présence d''un chien ou d''un lapin ne guérit évidemment aucune maladie, mais elle stimule la parole et l''attention de résidents qui sortaient peu de leur réserve, et apaise les tensions au moment des soins.</p>","options":["Elle réduit les coûts.","Elle favorise la communication des résidents.","Elle remplace une partie du personnel.","Elle soigne certaines maladies."]}'::jsonb, '{"answer":1}'::jsonb, 'Elle « stimule la parole et l''attention ».'),
  ('lo44tpce25', 'lo44tpde1ce', 25, 'qcm', 'Quelle critique est formulée sur ce spectacle ?', '{"doc":"<p>La mise en scène, d''une sobriété remarquable, laisse toute la place au texte et aux comédiens. On regrettera seulement que la seconde partie, étirée en longueur, affaiblisse la tension patiemment construite pendant la première heure.</p>","options":["Les comédiens jouent mal.","La seconde partie est trop longue.","Le texte est faible.","La mise en scène est trop chargée."]}'::jsonb, '{"answer":1}'::jsonb, '« la seconde partie, étirée en longueur ».'),
  ('lo44tpce26', 'lo44tpde1ce', 26, 'qcm', 'Pourquoi certaines villes limitent-elles ces locations ?', '{"doc":"<p>Les plateformes de location touristique ont transformé l''économie de nombreux centres historiques. Si elles procurent des revenus complémentaires aux propriétaires, elles réduisent l''offre de logements à l''année et contribuent à vider certains quartiers de leurs habitants permanents, au point que plusieurs villes ont décidé de limiter le nombre de nuitées autorisées.</p>","options":["Pour protéger les hôtels.","Pour préserver les logements des habitants.","Pour augmenter les impôts.","Pour réduire le tourisme étranger."]}'::jsonb, '{"answer":1}'::jsonb, 'Elles « réduisent l''offre de logements à l''année ».'),
  ('lo44tpce27', 'lo44tpde1ce', 27, 'qcm', 'Que reproche la chercheuse à l''usage de ce mot ?', '{"doc":"<p>La chercheuse souligne que le mot « résilience », à force d''être employé à tout propos, a perdu de sa précision. Appliqué aux individus comme aux villes ou aux économies, il tend à faire peser sur chacun la responsabilité de s''adapter aux crises, plutôt qu''à interroger les causes de celles-ci.</p>","options":["Il décrit mal les villes.","Il ne s''applique qu''aux individus.","Il est trop technique.","Il détourne l''attention des causes des crises."]}'::jsonb, '{"answer":3}'::jsonb, 'Il fait peser l''adaptation sur chacun « plutôt qu''à interroger les causes ».'),
  ('lo44tpce28', 'lo44tpde1ce', 28, 'qcm', 'Quelle idée l''auteur développe-t-il ?', '{"doc":"<p>Le progrès technique n''est pas neutre : chaque outil porte en lui une certaine conception de l''existence. Le GPS, en nous épargnant l''effort de nous orienter, nous dispense aussi de cette attention au paysage par laquelle on finissait par habiter un lieu. Ce que nous gagnons en efficacité, nous le perdons peut-être en familiarité avec le monde.</p>","options":["Nos outils transforment notre rapport au monde.","Le GPS est devenu indispensable.","La technique est toujours neutre.","Il faut refuser le progrès."]}'::jsonb, '{"answer":0}'::jsonb, '« chaque outil porte en lui une certaine conception de l''existence ».'),
  ('lo44tpce29', 'lo44tpde1ce', 29, 'qcm', 'Comment l''auteur conçoit-il l''ironie ?', '{"doc":"<p>L''ironie, disait-on autrefois, est la politesse du désespoir. Il faut sans doute nuancer : bien maniée, elle n''est ni fuite ni mépris, mais une manière de tenir le réel à distance juste assez pour le penser, sans se laisser écraser par lui ni prétendre le dominer.</p>","options":["Comme une distance qui permet de réfléchir.","Comme un moyen de dominer autrui.","Comme une forme de mépris.","Comme une fuite devant la réalité."]}'::jsonb, '{"answer":0}'::jsonb, '« une manière de tenir le réel à distance juste assez pour le penser ».')
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44tpde1pe', 'exam', 'TCF Pháp · Đề 1 : Expression écrite', 'TCF_TP', array['Production écrite']::text[], 'practice', null, 60, '<p><strong>Expression écrite : 60 minutes, 3 tâches.</strong> Respectez le nombre de mots demandé pour chaque tâche.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[]}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo44tppe1', 'lo44tpde1pe', 1, 'open', 'Tâche 1 (60 mots minimum, 120 mots maximum)' || chr(10) || 'Vous organisez un repas entre voisins dans la cour de votre immeuble. Écrivez un message aux habitants pour les inviter. Précisez la date, l''heure, le lieu et ce que chacun peut apporter.', '{}'::jsonb, '{}'::jsonb, null),
  ('lo44tppe2', 'lo44tpde1pe', 2, 'open', 'Tâche 2 (120 mots minimum, 150 mots maximum)' || chr(10) || 'Vous venez de déménager dans une nouvelle ville. Dans un courriel à un(e) ami(e), décrivez votre nouveau quartier et dites ce que vous en pensez.', '{}'::jsonb, '{}'::jsonb, null),
  ('lo44tppe3', 'lo44tpde1pe', 3, 'open', 'Tâche 3 (120 mots minimum, 180 mots maximum)' || chr(10) || 'Faut-il rendre les transports en commun gratuits ?' || chr(10) || '' || chr(10) || 'Document 1 : Plusieurs villes françaises ont rendu leurs bus gratuits. Les élus se félicitent d''une hausse importante de la fréquentation et d''un centre-ville moins encombré. Pour les familles modestes, la mesure représente aussi une économie non négligeable à la fin du mois.' || chr(10) || '' || chr(10) || 'Document 2 : La gratuité a un coût : ce que les voyageurs ne paient plus, ce sont les impôts locaux qui le financent. Certains experts rappellent aussi que les nouveaux passagers sont souvent d''anciens piétons ou cyclistes, et non des automobilistes. Mieux vaudrait, selon eux, investir dans la fréquence et la qualité du service.' || chr(10) || '' || chr(10) || 'Vous écrivez un article pour le site d''un journal. Dans une première partie (40 à 60 mots), présentez les deux points de vue. Dans une seconde partie (80 à 120 mots), donnez votre opinion en l''illustrant d''exemples.', '{}'::jsonb, '{}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo44tpde1po', 'exam', 'TCF Pháp · Đề 1 : Expression orale', 'TCF_TP', array['Production orale']::text[], 'practice', null, null, '<p><strong>Expression orale : 12 minutes environ, 3 tâches.</strong></p><p><strong>Tâche 1. Entretien dirigé</strong> (2 minutes, sans préparation) : présentez-vous. Parlez de vous, de votre famille, de votre travail ou de vos études, de vos loisirs et de vos projets.</p><p><strong>Tâche 2. Exercice en interaction</strong> (5 minutes 30, dont 2 minutes de préparation) : l''examinateur joue un rôle, vous lui posez des questions.</p><p><strong>Tâche 3. Expression d''un point de vue</strong> (4 minutes 30, sans préparation) : vous donnez votre opinion sur un sujet et vous la justifiez.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"bocTham":{"chuanBi":2,"phan":[{"ten":"Tâche 2. Exercice en interaction (5 min 30)","cachLam":"Posez des questions à l''examinateur pour obtenir les informations dont vous avez besoin.","soRut":1,"sujets":[{"ma":"1","html":"<p>Je suis votre ami(e). Je viens de rentrer d''un voyage en Corse. Vous voulez y aller cet été. Posez-moi des questions (transport, logement, activités, budget, etc.).</p>"},{"ma":"2","html":"<p>Je travaille à la mairie. Vous voulez inscrire votre enfant au centre de loisirs pendant les vacances. Posez-moi des questions (âge, horaires, activités, tarifs, etc.).</p>"},{"ma":"3","html":"<p>Je suis votre voisin(e). Je vends ma voiture. Vous êtes intéressé(e). Posez-moi des questions (prix, état, kilométrage, entretien, etc.).</p>"},{"ma":"4","html":"<p>Je suis bénévole dans une association d''aide aux devoirs. Vous voulez devenir bénévole. Posez-moi des questions (public, horaires, formation, matières, etc.).</p>"}]},{"ten":"Tâche 3. Expression d''un point de vue (4 min 30)","cachLam":"Donnez votre opinion et justifiez-la avec des arguments et des exemples.","soRut":1,"sujets":[{"ma":"A","html":"<p>Faut-il interdire la publicité destinée aux enfants ?</p>"},{"ma":"B","html":"<p>Faudrait-il consacrer plus d''heures au sport à l''école ?</p>"},{"ma":"C","html":"<p>Est-il préférable de voyager seul ou en groupe ? Pourquoi ?</p>"},{"ma":"D","html":"<p>Les réseaux sociaux rapprochent-ils ou éloignent-ils les gens ?</p>"}]}]}}'::jsonb, '2026-11-14T08:00:00.000Z') on conflict (id) do nothing;

